/**
 * HTML privado embebido para Vercel.
 * Evita depender de fs/includeFiles en tiempo de ejecución.
 */

export const HTML_INGRESO = "<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Ingresar | Observatorio Estelar UNAD CIP Turbo</title>\n    <link rel=\"icon\" type=\"image/jpeg\" href=\"logo.jpg\">\n    <style>\n        /* Pantalla de ingreso obligatoria: es lo primero que ve cualquier persona */\n        :root { --fondo: #05060a; --panel: #1f2833; --cian: #66fcf1; --oro: #e5b340; --verde: #45a29e; --texto: #dfe3e8; --suave: #9aa4b1; }\n        * { box-sizing: border-box; }\n        body { margin: 0; min-height: 100vh; color: var(--texto); font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; background: #05060a; display: flex; align-items: center; justify-content: center; padding: 24px 16px; }\n        #cielo { position: fixed; inset: 0; width: 100%; height: 100%; z-index: -1; background: radial-gradient(ellipse at 30% 10%, #131a2e 0%, #070912 45%, #030407 100%); }\n        .contenedor { width: 100%; max-width: 980px; display: grid; grid-template-columns: minmax(0, 1fr) 420px; gap: 48px; align-items: center; }\n        .presentacion { text-align: left; }\n        .emblema { width: 130px; height: 130px; border-radius: 50%; background: url('logo.jpg') center / 136% auto no-repeat; border: 3px solid var(--oro); box-shadow: 0 0 0 8px rgba(229, 179, 64, 0.12), 0 0 50px rgba(229, 179, 64, 0.35); margin-bottom: 22px; }\n        .presentacion h1 { font-size: clamp(2.2rem, 5vw, 3.6rem); line-height: 1.05; margin: 0 0 12px 0; color: var(--cian); text-shadow: 0 0 20px rgba(102, 252, 241, 0.45); letter-spacing: 0.03em; }\n        .presentacion p { color: var(--suave); font-size: 1.1rem; margin: 0 0 22px 0; max-width: 46ch; line-height: 1.6; }\n        /* Los pasos sí son una secuencia: por eso van numerados */\n        .pasos { list-style: none; padding: 0; margin: 0 0 22px 0; display: flex; flex-direction: column; gap: 10px; }\n        .pasos li { display: flex; gap: 12px; align-items: center; color: var(--texto); }\n        .pasos span { width: 28px; height: 28px; border-radius: 50%; display: grid; place-items: center; background: rgba(102, 252, 241, 0.12); border: 1px solid var(--cian); color: var(--cian); font-weight: bold; font-size: 0.9rem; flex-shrink: 0; }\n        .enlace-historia { color: var(--oro); text-decoration: none; font-weight: bold; }\n        .enlace-historia:hover { text-decoration: underline; }\n        .tarjeta { background: rgba(31, 40, 51, 0.92); border-radius: 18px; padding: 26px; border-top: 4px solid var(--oro); box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5); }\n        .tarjeta h2 { margin: 0 0 16px 0; font-size: 1.4rem; }\n        .pestanas { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; background: #0b0c10; padding: 5px; border-radius: 26px; margin-bottom: 18px; }\n        .pestanas button { background: transparent; color: #c5c6c7; border: none; padding: 10px; border-radius: 22px; cursor: pointer; font-weight: bold; font-size: 0.95rem; font-family: inherit; }\n        .pestanas button[aria-selected=\"true\"] { background: var(--oro); color: #0b0c10; }\n        .pestanas button:focus-visible, .formulario button:focus-visible { outline: 2px solid var(--cian); outline-offset: 2px; }\n        .formulario { display: flex; flex-direction: column; gap: 8px; }\n        .formulario[hidden] { display: none; }\n        label { font-size: 0.85rem; color: #c5c6c7; font-weight: bold; }\n        input { padding: 12px; border-radius: 8px; border: 1px solid var(--verde); background: #0b0c10; color: white; font-size: 1rem; width: 100%; font-family: inherit; }\n        input:focus { outline: 2px solid var(--cian); outline-offset: 1px; }\n        .campo-clave { position: relative; }\n        .campo-clave input { padding-right: 76px; }\n        .campo-clave button { position: absolute; right: 6px; top: 50%; transform: translateY(-50%); background: none; border: none; color: var(--cian); cursor: pointer; font-size: 0.85rem; padding: 6px; font-family: inherit; }\n        small { color: #8b95a1; font-size: 0.8rem; }\n        .enviar { background: var(--oro); color: #0b0c10; border: none; padding: 13px; font-weight: bold; cursor: pointer; border-radius: 8px; font-size: 1.05rem; margin-top: 8px; font-family: inherit; }\n        .enviar:disabled { opacity: 0.6; cursor: wait; }\n        .estado { min-height: 1.3em; margin: 2px 0 0 0; font-size: 0.92rem; }\n        .estado.error { color: #ff8a80; }\n        .estado.exito { color: var(--cian); }\n        .cambiar { background: none; border: none; color: var(--cian); cursor: pointer; font-size: 0.92rem; padding: 4px 0; text-align: center; font-family: inherit; }\n        @media (max-width: 860px) {\n            .contenedor { grid-template-columns: minmax(0, 1fr); gap: 26px; }\n            .presentacion { text-align: center; }\n            .emblema { margin: 0 auto 16px auto; width: 100px; height: 100px; }\n            .presentacion p { margin-left: auto; margin-right: auto; }\n            .pasos { align-items: center; }\n            .pasos li { width: 100%; max-width: 330px; text-align: left; }\n        }\n        /* En celulares angostos el formulario sube: los pasos ya se explican dentro del formulario */\n        @media (max-width: 520px) {\n            .pasos { display: none; }\n            .presentacion p { margin-bottom: 12px; }\n        }\n    </style>\n</head>\n<body>\n    <canvas id=\"cielo\" aria-hidden=\"true\"></canvas>\n\n    <main class=\"contenedor\">\n        <section class=\"presentacion\">\n            <div class=\"emblema\" role=\"img\" aria-label=\"Emblema del Observatorio Estelar UNAD CIP Turbo\"></div>\n            <h1>Observatorio Estelar</h1>\n            <p>UNAD | CIP Turbo. Ingresa con tu cuenta para explorar el telescopio, el equipo y la bitácora del proyecto.</p>\n            <ol class=\"pasos\">\n                <li><span>1</span> Crea tu cuenta con usuario y contraseña.</li>\n                <li><span>2</span> Ingresa y conoce al equipo.</li>\n                <li><span>3</span> Sube las fotos y videos de cada actividad.</li>\n            </ol>\n            <a class=\"enlace-historia\" href=\"historia-telescopio.html\">Leer la historia del telescopio sin cuenta</a>\n        </section>\n\n        <section class=\"tarjeta\" aria-label=\"Acceso\">\n            <div class=\"pestanas\" role=\"tablist\" aria-label=\"Acceso\">\n                <button type=\"button\" role=\"tab\" id=\"pestana-ingresar\" aria-selected=\"true\" onclick=\"mostrar('ingresar')\">Iniciar sesión</button>\n                <button type=\"button\" role=\"tab\" id=\"pestana-registrar\" aria-selected=\"false\" onclick=\"mostrar('registrar')\">Crear cuenta</button>\n            </div>\n\n            <form class=\"formulario\" id=\"form-ingresar\" onsubmit=\"enviar(event, 'iniciar')\">\n                <label for=\"ingreso-usuario\">Usuario</label>\n                <input type=\"text\" id=\"ingreso-usuario\" autocomplete=\"username\" autocapitalize=\"none\" spellcheck=\"false\" required>\n                <label for=\"ingreso-clave\">Contraseña</label>\n                <div class=\"campo-clave\">\n                    <input type=\"password\" id=\"ingreso-clave\" autocomplete=\"current-password\" required>\n                    <button type=\"button\" onclick=\"alternarClave('ingreso-clave', this)\">Mostrar</button>\n                </div>\n                <p class=\"estado\" id=\"estado-ingresar\" aria-live=\"polite\"></p>\n                <button type=\"submit\" class=\"enviar\">Ingresar</button>\n                <button type=\"button\" class=\"cambiar\" onclick=\"mostrar('registrar')\">¿No tienes cuenta? Créala aquí</button>\n            </form>\n\n            <form class=\"formulario\" id=\"form-registrar\" onsubmit=\"enviar(event, 'registrar')\" hidden>\n                <label for=\"registro-nombre\">Nombre completo</label>\n                <input type=\"text\" id=\"registro-nombre\" autocomplete=\"name\" maxlength=\"60\" required>\n                <label for=\"registro-usuario\">Usuario</label>\n                <input type=\"text\" id=\"registro-usuario\" autocomplete=\"username\" autocapitalize=\"none\" spellcheck=\"false\" maxlength=\"20\" pattern=\"[A-Za-z0-9._]{3,20}\" title=\"De 3 a 20 caracteres: letras sin tilde, números, punto o guion bajo\" required>\n                <small>De 3 a 20 caracteres: letras sin tilde, números, punto o guion bajo.</small>\n                <label for=\"registro-clave\">Contraseña</label>\n                <div class=\"campo-clave\">\n                    <input type=\"password\" id=\"registro-clave\" autocomplete=\"new-password\" minlength=\"8\" maxlength=\"72\" required>\n                    <button type=\"button\" onclick=\"alternarClave('registro-clave', this)\">Mostrar</button>\n                </div>\n                <label for=\"registro-clave2\">Repite la contraseña</label>\n                <input type=\"password\" id=\"registro-clave2\" autocomplete=\"new-password\" minlength=\"8\" maxlength=\"72\" required>\n                <small>Mínimo 8 caracteres. Guárdala bien: la necesitarás cada vez que ingreses desde otro equipo.</small>\n                <p class=\"estado\" id=\"estado-registrar\" aria-live=\"polite\"></p>\n                <button type=\"submit\" class=\"enviar\">Crear cuenta e ingresar</button>\n                <button type=\"button\" class=\"cambiar\" onclick=\"mostrar('ingresar')\">¿Ya tienes cuenta? Inicia sesión</button>\n            </form>\n        </section>\n    </main>\n\n    <script>\n        const API_CUENTAS = '/api/cuentas.php';\n\n        function mostrar(cual) {\n            document.getElementById('form-ingresar').hidden = cual !== 'ingresar';\n            document.getElementById('form-registrar').hidden = cual !== 'registrar';\n            document.getElementById('pestana-ingresar').setAttribute('aria-selected', String(cual === 'ingresar'));\n            document.getElementById('pestana-registrar').setAttribute('aria-selected', String(cual === 'registrar'));\n            document.getElementById(cual === 'ingresar' ? 'ingreso-usuario' : 'registro-nombre').focus();\n        }\n\n        function alternarClave(id, boton) {\n            const campo = document.getElementById(id);\n            const visible = campo.type === 'text';\n            campo.type = visible ? 'password' : 'text';\n            boton.textContent = visible ? 'Mostrar' : 'Ocultar';\n        }\n\n        function estado(cual, texto, clase = '') {\n            const elemento = document.getElementById(`estado-${cual}`);\n            elemento.textContent = texto;\n            elemento.className = 'estado' + (clase ? ' ' + clase : '');\n        }\n\n        // Crea la cuenta o inicia sesión; si todo sale bien, el servidor ya entrega el sitio completo\n        async function enviar(evento, accion) {\n            evento.preventDefault();\n            const cual = accion === 'iniciar' ? 'ingresar' : 'registrar';\n            const datos = new FormData();\n            datos.append('accion', accion);\n            if (accion === 'iniciar') {\n                datos.append('usuario', document.getElementById('ingreso-usuario').value.trim());\n                datos.append('clave', document.getElementById('ingreso-clave').value);\n            } else {\n                const clave = document.getElementById('registro-clave').value;\n                if (clave !== document.getElementById('registro-clave2').value) {\n                    estado(cual, 'Las contraseñas no coinciden. Escríbelas de nuevo.', 'error');\n                    return;\n                }\n                datos.append('nombre', document.getElementById('registro-nombre').value.trim());\n                datos.append('usuario', document.getElementById('registro-usuario').value.trim());\n                datos.append('clave', clave);\n            }\n            const boton = evento.target.querySelector('.enviar');\n            boton.disabled = true;\n            estado(cual, accion === 'iniciar' ? 'Verificando…' : 'Creando tu cuenta…');\n            try {\n                const respuesta = await fetch(API_CUENTAS, { method: 'POST', body: datos, credentials: 'same-origin' });\n                const resultado = await respuesta.json().catch(() => ({}));\n                if (!respuesta.ok || !resultado.ok) throw new Error(resultado.error || `El servidor respondió con error ${respuesta.status}.`);\n                estado(cual, `¡Bienvenido, ${resultado.usuario.nombre}! Entrando…`, 'exito');\n                location.replace('./');\n            } catch (error) {\n                estado(cual, (error instanceof TypeError && /fetch|network|conex/i.test(error.message)) ? 'No fue posible contactar el servidor. La página puede tener Internet, pero el backend no está respondiendo. Revisa el despliegue y la configuración de Vercel.' : error.message, 'error');\n                boton.disabled = false;\n            }\n        }\n\n        // Cielo estrellado suave detrás del formulario\n        (function iniciarCielo() {\n            const lienzo = document.getElementById('cielo');\n            const ctx = lienzo.getContext('2d');\n            const quieto = window.matchMedia('(prefers-reduced-motion: reduce)').matches;\n            let estrellas = [];\n            function crear() {\n                const escala = window.devicePixelRatio || 1;\n                lienzo.width = innerWidth * escala;\n                lienzo.height = innerHeight * escala;\n                ctx.setTransform(escala, 0, 0, escala, 0, 0);\n                estrellas = Array.from({ length: Math.floor((innerWidth * innerHeight) / 3500) }, () => ({\n                    x: Math.random() * innerWidth, y: Math.random() * innerHeight,\n                    r: Math.random() * 1.3 + 0.2, f: Math.random() * Math.PI * 2, v: Math.random() * 0.02 + 0.005\n                }));\n            }\n            function dibujar() {\n                ctx.clearRect(0, 0, innerWidth, innerHeight);\n                estrellas.forEach(s => {\n                    if (!quieto) s.f += s.v;\n                    ctx.beginPath();\n                    ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2);\n                    ctx.fillStyle = `rgba(255,255,255,${0.45 + Math.sin(s.f) * 0.4})`;\n                    ctx.fill();\n                });\n                if (!quieto) requestAnimationFrame(dibujar);\n            }\n            crear();\n            dibujar();\n            addEventListener('resize', () => { crear(); if (quieto) dibujar(); });\n        })();\n\n        document.getElementById('ingreso-usuario').focus();\n    </script>\n</body>\n</html>\n";

export const HTML_SITIO = "<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Observatorio Estelar UNAD | CIP TURBO</title>\n    <link rel=\"icon\" type=\"image/jpeg\" href=\"logo.jpg\">\n    <style>\n        /* ESTILOS GENERALES */\n        body { background-color: #05060a; color: white; margin: 0; font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; }\n        /* Cielo estrellado animado: canvas fijo detrás de todo el contenido */\n        #cielo-estrellado { position: fixed; inset: 0; width: 100%; height: 100%; z-index: -1; display: block; background: radial-gradient(ellipse at 20% 10%, #131a2e 0%, #070912 45%, #030407 100%); }\n        .navbar { display: flex; align-items: center; padding: 15px 30px; background-color: rgba(31, 40, 51, 0.8); border-bottom: 2px solid #e5b340; backdrop-filter: blur(6px); position: sticky; top: 0; z-index: 50; }\n        /* Logo real recortado al emblema circular; al hacer clic se abre completo */\n        .logo-circulo { width: 70px; height: 70px; border-radius: 50%; background-image: url('logo.jpg'); background-size: 136% auto; background-position: center; background-repeat: no-repeat; border: 2px solid #e5b340; margin-right: 20px; box-shadow: 0 0 15px rgba(229, 179, 64, 0.4); cursor: pointer; padding: 0; transition: transform 0.3s ease, box-shadow 0.3s ease; }\n        .logo-circulo:hover, .logo-circulo:focus-visible { transform: scale(1.08) rotate(-4deg); box-shadow: 0 0 25px rgba(229, 179, 64, 0.8); outline: none; }\n        .navbar h1 { font-size: 1.5rem; color: #c5c6c7; margin: 0; }\n        /* Botón para ver la página en pantalla completa (presentaciones) */\n        .btn-pantalla { margin-left: auto; background: transparent; color: #66fcf1; border: 1px solid #66fcf1; padding: 8px 16px; border-radius: 25px; cursor: pointer; font-size: 0.95rem; font-weight: bold; transition: background 0.2s ease, color 0.2s ease; }\n        .btn-pantalla:hover, .btn-pantalla:focus-visible { background: #66fcf1; color: #0b0c10; outline: none; }\n        html { scroll-behavior: smooth; }\n        /* Portada: ocupa la pantalla completa bajo la barra, como la entrada de un sitio web */\n        .hero-section { text-align: center; padding: 60px 20px; min-height: calc(100vh - 104px); box-sizing: border-box; display: flex; flex-direction: column; align-items: center; justify-content: center; background: radial-gradient(circle at 50% 45%, rgba(31, 40, 51, 0.6) 0%, rgba(11, 12, 16, 0) 60%); }\n        .hero-emblema { width: 170px; height: 170px; border-radius: 50%; background: url('logo.jpg') center / 136% auto no-repeat; border: 3px solid #e5b340; box-shadow: 0 0 0 8px rgba(229, 179, 64, 0.12), 0 0 60px rgba(229, 179, 64, 0.35); margin-bottom: 26px; }\n        .titulo-principal { font-size: clamp(2.3rem, 6vw, 5.2rem); letter-spacing: 0.04em; color: #66fcf1; text-shadow: 0 0 20px rgba(102, 252, 241, 0.5); margin: 0 0 14px 0; line-height: 1.05; }\n        .hero-lema { font-size: clamp(1rem, 1.6vw, 1.35rem); color: #c5c6c7; margin: 0 0 34px 0; max-width: 60ch; }\n        .hero-acciones { display: flex; gap: 14px; flex-wrap: wrap; justify-content: center; }\n        .hero-acciones a { text-decoration: none; font-weight: bold; padding: 13px 26px; border-radius: 30px; font-size: 1.05rem; transition: background 0.2s ease, color 0.2s ease, box-shadow 0.2s ease; }\n        .accion-principal { background: #66fcf1; color: #0b0c10; box-shadow: 0 0 24px rgba(102, 252, 241, 0.35); }\n        .accion-principal:hover, .accion-principal:focus-visible { box-shadow: 0 0 36px rgba(102, 252, 241, 0.6); outline: none; }\n        .accion-secundaria { color: #e5b340; border: 1px solid #e5b340; }\n        .accion-secundaria:hover, .accion-secundaria:focus-visible { background: #e5b340; color: #0b0c10; outline: none; }\n        /* Menú de navegación del sitio */\n        .menu-sitio { display: flex; gap: 4px; margin-left: 40px; list-style: none; padding: 0; }\n        .menu-sitio a { color: #c5c6c7; text-decoration: none; padding: 8px 14px; border-radius: 20px; font-size: 0.98rem; transition: color 0.2s ease, background 0.2s ease; }\n        .menu-sitio a:hover, .menu-sitio a:focus-visible { color: #fff; background: rgba(102, 252, 241, 0.12); outline: none; }\n        /* Pie de página */\n        .pie-sitio { border-top: 1px solid rgba(229, 179, 64, 0.35); background: rgba(10, 12, 18, 0.9); padding: 36px 20px; }\n        .pie-contenido { max-width: 1200px; margin: 0 auto; display: flex; align-items: center; gap: 22px; flex-wrap: wrap; justify-content: space-between; color: #8b95a1; font-size: 0.92rem; }\n        .pie-marca { display: flex; align-items: center; gap: 14px; }\n        .pie-marca span.pie-logo { width: 48px; height: 48px; border-radius: 50%; background: url('logo.jpg') center / 136% auto no-repeat; border: 2px solid #e5b340; flex-shrink: 0; }\n        .pie-marca strong { color: #fff; display: block; font-size: 1rem; }\n        .pie-sitio a { color: #66fcf1; text-decoration: none; }\n        .pie-sitio a:hover { text-decoration: underline; }\n        .comienzo-section { background-color: rgba(18, 21, 28, 0.55); padding: 50px 20px; text-align: center; backdrop-filter: blur(2px); }\n        \n        .explicacion-container { display: flex; justify-content: center; align-items: center; gap: 40px; flex-wrap: wrap; max-width: 900px; margin: 0 auto; }\n        .animacion-telescopio { width: 150px; height: 150px; }\n        .tube, .lens { transform-origin: 50px 55px; animation: explorar 6s infinite alternate ease-in-out; }\n        @keyframes explorar { 0% { transform: rotate(-10deg); } 50% { transform: rotate(-45deg); } 100% { transform: rotate(-5deg); } }\n        .texto-explicacion { max-width: 400px; text-align: left; font-size: 1.1rem; color: #c5c6c7; }\n        /* Las secciones no quedan tapadas por la barra superior fija al navegar */\n        section { scroll-margin-top: 110px; }\n        .pista-observar { color: #c5c6c7; font-size: 0.95rem; margin: 5px 0 0 0; }\n        .pista-observar strong { color: #66fcf1; }\n\n        /* ===================== TELESCOPIO 3D (CSS puro, funciona sin internet) ===================== */\n        .telescopio3d-section { padding: 60px 20px; }\n        .telescopio3d-contenido { max-width: 1100px; margin: 0 auto; display: grid; grid-template-columns: minmax(0, 1.1fr) minmax(0, 1fr); gap: 40px; align-items: center; }\n        .telescopio3d-section h2 { color: #e5b340; font-size: 2.2rem; margin: 0 0 12px 0; }\n        .telescopio3d-intro { color: #c5c6c7; font-size: 1.05rem; line-height: 1.6; margin: 0 0 20px 0; max-width: 60ch; }\n        .escenario3d { position: relative; height: 480px; perspective: 1100px; cursor: grab; touch-action: pan-y; border-radius: 50%; background: radial-gradient(circle at 50% 55%, rgba(102, 252, 241, 0.10) 0%, rgba(102, 252, 241, 0) 60%); outline: none; }\n        .escenario3d:active { cursor: grabbing; }\n        .escenario3d:focus-visible { box-shadow: 0 0 0 2px #66fcf1; }\n        /* Origen del modelo: punto de apoyo de la montura */\n        .modelo3d { position: absolute; left: 50%; top: 42%; width: 0; height: 0; transform-style: preserve-3d; transform: scale(var(--escala3d, 1)) rotateX(-12deg) rotateY(var(--giro, 30deg)); }\n        .modelo3d div { position: absolute; transform-style: preserve-3d; }\n        .modelo3d .cara, .modelo3d .tapa { backface-visibility: visible; transition: box-shadow 0.3s ease; }\n        .modelo3d .tapa { border-radius: 50%; }\n        /* Resalta la pieza elegida en la lista de partes */\n        .modelo3d .resaltado .cara, .modelo3d .resaltado .tapa, .modelo3d .resaltado.tapa { box-shadow: inset 0 0 0 200px rgba(102, 252, 241, 0.45); }\n        .sombra-suelo { position: absolute; left: 50%; top: 88%; width: 320px; height: 60px; margin-left: -160px; border-radius: 50%; background: radial-gradient(ellipse, rgba(0, 0, 0, 0.6) 0%, rgba(0, 0, 0, 0) 70%); }\n        .pista-giro { position: absolute; bottom: 6px; left: 0; right: 0; text-align: center; color: #8b95a1; font-size: 0.85rem; margin: 0; pointer-events: none; }\n        .lista-partes { display: flex; flex-wrap: wrap; gap: 8px; margin: 0 0 18px 0; padding: 0; list-style: none; }\n        .lista-partes button { background: rgba(31, 40, 51, 0.85); color: #c5c6c7; border: 1px solid #2e3b4a; padding: 8px 14px; border-radius: 20px; cursor: pointer; font-size: 0.95rem; transition: border-color 0.2s ease, color 0.2s ease; }\n        .lista-partes button:hover, .lista-partes button:focus-visible { border-color: #66fcf1; color: #fff; outline: none; }\n        .lista-partes button[aria-pressed=\"true\"] { background: #66fcf1; color: #0b0c10; border-color: #66fcf1; font-weight: bold; }\n        .detalle-parte { background: rgba(31, 40, 51, 0.85); border-left: 4px solid #e5b340; border-radius: 0 12px 12px 0; padding: 18px 22px; min-height: 120px; }\n        .detalle-parte h3 { margin: 0 0 8px 0; color: #fff; font-size: 1.3rem; }\n        .detalle-parte p { margin: 0; color: #c5c6c7; line-height: 1.6; }\n\n        /* ===================== CONSTELACIÓN DEL EQUIPO ===================== */\n        .equipo-section { padding: 60px 20px 90px 20px; text-align: center; }\n        .equipo-section h2 { font-size: 2.2rem; margin-bottom: 6px; }\n        .leyenda-roles { display: flex; flex-wrap: wrap; justify-content: center; gap: 18px; margin: 18px 0 10px 0; padding: 0; list-style: none; color: #c5c6c7; font-size: 0.9rem; }\n        .leyenda-roles li::before { content: ''; display: inline-block; width: 10px; height: 10px; border-radius: 50%; margin-right: 7px; background: var(--color-rol); box-shadow: 0 0 8px var(--color-rol); vertical-align: middle; }\n        .constelacion { position: relative; max-width: 1000px; aspect-ratio: 1000 / 620; margin: 30px auto 0 auto; }\n        .lineas-constelacion { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }\n        .lineas-constelacion line { stroke: rgba(197, 198, 199, 0.45); stroke-width: 1.5; stroke-dasharray: 6 6; }\n        .lineas-constelacion circle { fill: #fff; }\n        /* Color del anillo según el rol: la leyenda explica el código */\n        .nodo-integrante { --color-rol: #45a29e; position: absolute; left: var(--x); top: var(--y); transform: translate(-50%, -52px); display: flex; flex-direction: column; align-items: center; background: none; border: none; color: #fff; cursor: pointer; padding: 0; font-family: inherit; width: 170px; }\n        .nodo-director { --color-rol: #a66bff; }\n        .nodo-lider { --color-rol: #e5b340; }\n        .nodo-creador { --color-rol: #66fcf1; }\n        .nodo-investigador { --color-rol: #45a29e; }\n        .icono-integrante { width: 104px; height: 104px; border-radius: 50%; overflow: hidden; border: 3px solid var(--color-rol); box-shadow: 0 0 0 5px rgba(5, 6, 10, 0.9), 0 0 24px var(--color-rol); background: #0b0c10; transition: transform 0.3s ease, box-shadow 0.3s ease; }\n        /* Recorte al rostro: excluye el cartel impreso en la imagen original */\n        .icono-integrante img { width: 100%; height: 100%; object-fit: cover; object-position: 50% 8%; transform: scale(1.45); transform-origin: 50% 22%; display: block; }\n        .nodo-integrante:hover .icono-integrante, .nodo-integrante:focus-visible .icono-integrante { transform: scale(1.1); box-shadow: 0 0 0 5px rgba(5, 6, 10, 0.9), 0 0 40px var(--color-rol); }\n        .nodo-integrante:focus-visible { outline: none; }\n        .nodo-integrante:focus-visible .nodo-nombre { text-decoration: underline; }\n        /* Fondo detrás del texto para que las líneas de la constelación no lo crucen */\n        .nodo-nombre, .nodo-rol { background: rgba(5, 6, 10, 0.78); padding: 1px 8px; border-radius: 6px; }\n        .nodo-nombre { margin-top: 10px; font-size: 1.1rem; font-weight: bold; text-shadow: 0 2px 6px #000; }\n        .nodo-rol { font-size: 0.85rem; color: var(--color-rol); font-weight: bold; text-shadow: 0 2px 6px #000; }\n        /* Aparición orquestada: las líneas se trazan y luego aparecen los integrantes */\n        .constelacion.preparada line { stroke-dashoffset: 400; stroke-dasharray: 400; }\n        .constelacion.preparada .nodo-integrante { opacity: 0; }\n        .constelacion.visible line { stroke-dasharray: 400; stroke-dashoffset: 0; transition: stroke-dashoffset 1.6s ease-out; }\n        .constelacion.visible .nodo-integrante { opacity: 1; transition: opacity 0.6s ease calc(var(--orden) * 0.12s + 0.4s); }\n\n        /* ===================== CIELO PROFUNDO (colores intercambiables) ===================== */\n        @property --c1 { syntax: '<color>'; inherits: true; initial-value: #ff4fa3; }\n        @property --c2 { syntax: '<color>'; inherits: true; initial-value: #7b3ff2; }\n        @property --c3 { syntax: '<color>'; inherits: true; initial-value: #2bb6ff; }\n        .cielo-profundo { position: relative; overflow: hidden; min-height: 620px; display: flex; align-items: center; padding: 60px 20px 180px 20px; box-sizing: border-box; background: #03040a; transition: --c1 1.2s ease, --c2 1.2s ease, --c3 1.2s ease; border-top: 1px solid rgba(255, 255, 255, 0.06); }\n        .nebulosa { position: absolute; inset: -10%; pointer-events: none; background:\n            radial-gradient(ellipse 38% 30% at 68% 38%, color-mix(in srgb, var(--c1) 75%, transparent) 0%, transparent 70%),\n            radial-gradient(ellipse 45% 35% at 78% 55%, color-mix(in srgb, var(--c2) 70%, transparent) 0%, transparent 72%),\n            radial-gradient(ellipse 30% 45% at 55% 30%, color-mix(in srgb, var(--c3) 55%, transparent) 0%, transparent 70%),\n            radial-gradient(ellipse 60% 40% at 20% 80%, color-mix(in srgb, var(--c2) 35%, transparent) 0%, transparent 70%);\n            filter: blur(30px); animation: respirar 18s ease-in-out infinite alternate; }\n        @keyframes respirar { from { transform: scale(1) rotate(0deg); } to { transform: scale(1.08) rotate(3deg); } }\n        /* Estrellas brillantes con destellos en cruz */\n        .astro { position: absolute; width: 4px; height: 4px; border-radius: 50%; background: #fff; box-shadow: 0 0 10px 3px color-mix(in srgb, var(--c3) 70%, #fff); }\n        .astro::before, .astro::after { content: ''; position: absolute; left: 50%; top: 50%; background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.85), transparent); }\n        .astro::before { width: 40px; height: 1px; transform: translate(-50%, -50%); }\n        .astro::after { width: 1px; height: 40px; transform: translate(-50%, -50%); background: linear-gradient(0deg, transparent, rgba(255, 255, 255, 0.85), transparent); }\n        .astro.grande { width: 6px; height: 6px; }\n        .astro.grande::before { width: 70px; }\n        .astro.grande::after { height: 70px; }\n        .horizonte-turbo { position: absolute; left: 0; right: 0; bottom: 0; width: 100%; height: 200px; pointer-events: none; }\n        .panel-cielo { position: relative; z-index: 1; max-width: 460px; background: rgba(5, 6, 14, 0.62); backdrop-filter: blur(6px); border: 1px solid rgba(255, 255, 255, 0.12); border-radius: 16px; padding: 28px; margin-left: max(0px, calc((100% - 1100px) / 2)); }\n        .panel-cielo h2 { margin: 0 0 6px 0; font-size: 2.2rem; color: #fff; }\n        .panel-cielo .subtitulo-cielo { margin: 0 0 18px 0; color: #c5c6c7; }\n        .temas-cielo { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 20px; }\n        .temas-cielo button { display: flex; align-items: center; gap: 8px; background: rgba(255, 255, 255, 0.06); color: #e6e6e6; border: 1px solid rgba(255, 255, 255, 0.18); padding: 8px 14px; border-radius: 20px; cursor: pointer; font-size: 0.92rem; transition: border-color 0.2s ease; }\n        .temas-cielo button:hover, .temas-cielo button:focus-visible { border-color: #fff; outline: none; }\n        .temas-cielo button[aria-pressed=\"true\"] { background: #fff; color: #05060a; font-weight: bold; }\n        .muestra-color { width: 14px; height: 14px; border-radius: 50%; flex-shrink: 0; }\n        /* Miniatura de la foto real dentro de cada botón, con anillo del color del objeto */\n        .miniatura-objeto { width: 30px; height: 30px; border-radius: 50%; object-fit: cover; flex-shrink: 0; border: 2px solid var(--anillo); margin-left: -6px; }\n        .foto-real { margin: 0 0 16px 0; border-radius: 12px; overflow: hidden; border: 1px solid rgba(255, 255, 255, 0.15); background: #000; }\n        .foto-real img { width: 100%; aspect-ratio: 16 / 9; object-fit: cover; display: block; transition: opacity 0.4s ease; }\n        .foto-real img.cambiando { opacity: 0; }\n        .foto-real figcaption { font-size: 0.78rem; color: #aab2bd; padding: 7px 10px; background: rgba(0, 0, 0, 0.55); }\n        .foto-real figcaption a { color: #cfd8e3; }\n        .objeto-cielo h3 { margin: 0 0 8px 0; font-size: 1.4rem; color: color-mix(in srgb, var(--c3) 45%, #fff); }\n        .objeto-cielo p { margin: 0 0 10px 0; color: #d7d9dc; line-height: 1.6; }\n        .objeto-cielo .cuando-verlo { color: #fff; font-size: 0.95rem; }\n        .objeto-cielo .cuando-verlo strong { color: color-mix(in srgb, var(--c1) 55%, #fff); }\n        /* Figura ilustrada de cada objeto: solo la elegida se ve; al cambiar se desvanece y la nueva se traza */\n        .figura-cielo { position: absolute; right: max(20px, calc((100% - 1100px) / 2)); top: 50%; transform: translateY(-58%); width: min(540px, 46vw); height: auto; overflow: visible; pointer-events: none; }\n        .figura-cielo .figura { opacity: 0; transform: scale(0.9); transform-origin: 250px 250px; transition: opacity 0.8s ease, transform 1s ease; }\n        .figura-cielo .figura.activa { opacity: 1; transform: scale(1); }\n        .figura-cielo .trazo { fill: none; stroke: rgba(255, 255, 255, 0.55); stroke-width: 1.5; stroke-dasharray: 600; stroke-dashoffset: 600; transition: stroke-dashoffset 1.4s ease 0.3s; }\n        .figura-cielo .figura.activa .trazo { stroke-dashoffset: 0; }\n        .figura-cielo .etiqueta-fig { fill: #fff; font-size: 14px; font-family: 'Segoe UI', Tahoma, sans-serif; paint-order: stroke; stroke: rgba(0, 0, 0, 0.85); stroke-width: 3px; stroke-linejoin: round; opacity: 0; transition: opacity 0.6s ease 1s; }\n        .figura-cielo .figura.activa .etiqueta-fig { opacity: 0.95; }\n        .figura-cielo .destello line { stroke: rgba(255, 255, 255, 0.75); stroke-width: 1; }\n        .animacion-telescopio { cursor: pointer; border-radius: 50%; transition: filter 0.3s ease; background: none; border: none; padding: 0; }\n        .animacion-telescopio:hover, .animacion-telescopio:focus-visible { filter: drop-shadow(0 0 12px rgba(229, 179, 64, 0.7)); outline: none; }\n\n        .bitacora-section { background-color: rgba(18, 21, 28, 0.55); padding: 60px 20px 70px 20px; text-align: center; border-top: 2px dashed #45a29e; }\n        .bitacora-section h2 { font-size: 2.2rem; margin-bottom: 6px; }\n        /* Escritorio: formulario fijo a la izquierda y galería amplia a la derecha */\n        .bitacora-contenido { max-width: 1200px; margin: 0 auto; display: grid; grid-template-columns: 380px minmax(0, 1fr); gap: 30px; align-items: start; text-align: left; }\n        .form-multimedia { background: #1f2833; padding: 20px; border-radius: 10px; display: flex; flex-direction: column; gap: 10px; position: sticky; top: 124px; }\n        .form-multimedia input, .form-multimedia select { padding: 10px; border-radius: 5px; border: 1px solid #45a29e; background: #0b0c10; color: white; }\n        .form-multimedia button { background: #66fcf1; color: #0b0c10; border: none; padding: 10px; font-weight: bold; cursor: pointer; border-radius: 5px; }\n        .galeria-bitacora { display: grid; grid-template-columns: repeat(auto-fill, minmax(250px, 1fr)); gap: 20px; }\n        .item-media { background: #1f2833; padding: 10px; border-radius: 10px; }\n        .item-media img, .item-media video, .item-media iframe { width: 100%; height: 200px; object-fit: cover; border-radius: 5px; background: #000; }\n        /* Bitácora compartida: estado, ayudas y mensajes */\n        .modo-bitacora { max-width: 600px; margin: 0 auto 16px auto; padding: 10px 14px; border-radius: 8px; font-size: 0.92rem; background: rgba(31, 40, 51, 0.8); border: 1px solid #2e3b4a; color: #c5c6c7; }\n        .modo-bitacora.nube { border-color: #45a29e; color: #dffaf7; }\n        .form-multimedia { text-align: left; min-width: 0; }\n        /* Los campos no deben sobresalir del formulario en pantallas angostas */\n        .form-multimedia input, .form-multimedia select { box-sizing: border-box; width: 100%; min-width: 0; }\n        .form-multimedia > div { display: flex; flex-direction: column; gap: 6px; }\n        .form-multimedia > div[hidden] { display: none; }\n        .etiqueta-campo { font-size: 0.85rem; color: #c5c6c7; font-weight: bold; }\n        .ayuda-campo { color: #8b95a1; font-size: 0.8rem; }\n        .form-multimedia input[type=\"file\"] { cursor: pointer; }\n        .form-multimedia button:disabled { opacity: 0.6; cursor: wait; }\n        #progreso-subida { width: 100%; height: 10px; accent-color: #66fcf1; }\n        .estado-bitacora { margin: 0; min-height: 1.2em; font-size: 0.9rem; color: #c5c6c7; }\n        .estado-bitacora.error { color: #ff8a80; }\n        .estado-bitacora.exito { color: #66fcf1; }\n        .item-media h4 { margin: 10px 0 0 0; color: #66fcf1; overflow-wrap: anywhere; }\n        .item-media .fecha-media { margin: 4px 0 0 0; color: #8b95a1; font-size: 0.8rem; }\n        .item-media .btn-borrar { margin-top: 10px; background: #ff4c4c; color: white; border: none; padding: 6px; cursor: pointer; border-radius: 3px; width: 100%; }\n        .galeria-vacia { color: #8b95a1; }\n        \n        #modal-bienvenida { position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0, 0, 0, 0.95); display: flex; align-items: center; justify-content: center; z-index: 1000; }\n        .modal-content { background: #1f2833; padding: 40px; border-radius: 15px; text-align: center; border: 2px solid #66fcf1; max-width: 500px; }\n        .modal-content img { width: 100%; max-height: 250px; object-fit: cover; border-radius: 10px; margin: 15px 0; border: 2px solid #e5b340; }\n\n        /* ===================== BIENVENIDA CON LA FOTO DEL EQUIPO ===================== */\n        .modal-content.modal-equipo { max-width: 760px; padding: 26px; max-height: 94vh; overflow-y: auto; box-sizing: border-box; margin: 0 16px; }\n        .modal-content.modal-equipo img { max-height: none; height: auto; object-fit: contain; margin: 0 0 18px 0; }\n        .modal-content.modal-equipo h2 { margin: 0 0 8px 0; font-size: 1.8rem; color: #66fcf1; }\n        .modal-content.modal-equipo p { color: #c5c6c7; margin: 0 auto; max-width: 56ch; line-height: 1.5; }\n\n        /* ===================== GUÍA DE ARMADO ===================== */\n        .guia-armado { max-width: 1100px; margin: 60px auto 0 auto; background: rgba(18, 21, 28, 0.8); border: 1px solid #2e3b4a; border-radius: 16px; padding: 28px; }\n        .guia-armado h3 { margin: 0 0 6px 0; font-size: 1.8rem; color: #e5b340; }\n        .guia-armado > p { margin: 0 0 18px 0; color: #c5c6c7; }\n        .aviso-sol { display: flex; gap: 10px; align-items: flex-start; background: rgba(255, 90, 60, 0.12); border: 1px solid rgba(255, 120, 90, 0.55); color: #ffd2c6; border-radius: 10px; padding: 12px 14px; margin-bottom: 20px; font-size: 0.95rem; }\n        .pestanas-guia { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 20px; }\n        .pestanas-guia button { background: transparent; color: #c5c6c7; border: 1px solid #45a29e; padding: 10px 16px; border-radius: 24px; cursor: pointer; font-size: 0.98rem; }\n        .pestanas-guia button[aria-selected=\"true\"] { background: #45a29e; color: #0b0c10; font-weight: bold; }\n        .pestanas-guia button:focus-visible { outline: 2px solid #66fcf1; outline-offset: 2px; }\n        .cuerpo-guia { display: grid; grid-template-columns: minmax(0, 300px) minmax(0, 1fr); gap: 26px; }\n        .indice-pasos { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 6px; counter-reset: paso; }\n        .indice-pasos button { width: 100%; text-align: left; display: flex; gap: 10px; align-items: center; background: rgba(31, 40, 51, 0.7); color: #c5c6c7; border: 1px solid transparent; padding: 9px 12px; border-radius: 10px; cursor: pointer; font-size: 0.92rem; }\n        .indice-pasos button[aria-current=\"step\"] { border-color: #66fcf1; color: #fff; }\n        .indice-pasos .numero-paso { flex-shrink: 0; width: 26px; height: 26px; border-radius: 50%; display: grid; place-items: center; background: #0b0c10; border: 1px solid #45a29e; font-weight: bold; font-size: 0.85rem; }\n        .indice-pasos .hecho .numero-paso { background: #45a29e; color: #0b0c10; }\n        .paso-actual { background: rgba(31, 40, 51, 0.85); border-radius: 14px; padding: 24px; border-top: 4px solid #66fcf1; }\n        .paso-actual .contador-paso { color: #66fcf1; font-weight: bold; margin: 0 0 6px 0; }\n        .paso-actual h4 { font-size: 1.5rem; margin: 0 0 12px 0; color: #fff; }\n        .paso-actual .texto-paso { color: #d7d9dc; line-height: 1.65; margin: 0 0 14px 0; max-width: 70ch; }\n        .paso-actual .consejo-paso { background: rgba(229, 179, 64, 0.1); border-left: 3px solid #e5b340; padding: 10px 14px; border-radius: 0 8px 8px 0; color: #f1dca6; margin: 0 0 18px 0; }\n        .barra-avance { height: 8px; background: #0b0c10; border-radius: 4px; overflow: hidden; margin-bottom: 18px; }\n        .barra-avance span { display: block; height: 100%; background: linear-gradient(90deg, #45a29e, #66fcf1); transition: width 0.4s ease; }\n        .controles-paso { display: flex; flex-wrap: wrap; gap: 10px; align-items: center; }\n        .controles-paso button { background: #1f2833; color: #66fcf1; border: 1px solid #66fcf1; padding: 9px 16px; border-radius: 22px; cursor: pointer; font-weight: bold; }\n        .controles-paso button:disabled { opacity: 0.4; cursor: default; }\n        .controles-paso label { display: flex; gap: 8px; align-items: center; color: #c5c6c7; cursor: pointer; margin-left: auto; }\n        .controles-paso input[type=\"checkbox\"] { width: 18px; height: 18px; accent-color: #45a29e; }\n\n        /* ===================== HISTORIA Y QR ===================== */\n        .historia-section { padding: 60px 20px; background: rgba(18, 21, 28, 0.55); }\n        .historia-contenido { max-width: 1100px; margin: 0 auto; display: grid; grid-template-columns: minmax(0, 1fr) 320px; gap: 40px; align-items: center; }\n        .historia-section h2 { color: #e5b340; font-size: 2.2rem; margin: 0 0 12px 0; }\n        .historia-section p { color: #c5c6c7; line-height: 1.6; max-width: 60ch; }\n        .hitos-resumen { display: flex; flex-wrap: wrap; gap: 8px; margin: 18px 0 24px 0; padding: 0; list-style: none; }\n        .hitos-resumen li { background: rgba(31, 40, 51, 0.85); border: 1px solid #2e3b4a; border-radius: 20px; padding: 6px 12px; font-size: 0.9rem; color: #dfe3e8; }\n        .hitos-resumen strong { color: #66fcf1; }\n        .tarjeta-qr { background: #f4f6f8; color: #0b0c10; border-radius: 18px; padding: 22px; text-align: center; box-shadow: 0 0 40px rgba(102, 252, 241, 0.2); }\n        .tarjeta-qr canvas { width: 100%; max-width: 250px; height: auto; image-rendering: pixelated; display: block; margin: 0 auto 12px auto; }\n        .tarjeta-qr strong { display: block; font-size: 1.05rem; }\n        .tarjeta-qr small { color: #4a5563; display: block; margin-top: 4px; overflow-wrap: anywhere; }\n        .tarjeta-qr .qr-no-disponible { color: #4a5563; font-size: 0.92rem; margin: 0 0 12px 0; }\n        .acciones-historia { display: flex; flex-wrap: wrap; gap: 12px; }\n        .acciones-historia button { background: transparent; }\n        .acciones-historia button:disabled { opacity: 0.45; cursor: default; }\n        .acciones-historia a, .acciones-historia button { text-decoration: none; font-weight: bold; padding: 11px 22px; border-radius: 26px; font-size: 1rem; cursor: pointer; font-family: inherit; }\n\n        /* ===================== COMPAÑEROS: REGISTRO E INGRESO ===================== */\n        .companeros-section { padding: 60px 20px; }\n        .companeros-contenido { max-width: 1100px; margin: 0 auto; display: grid; grid-template-columns: minmax(0, 1fr) 420px; gap: 40px; align-items: start; }\n        .companeros-section h2 { font-size: 2.2rem; margin: 0 0 12px 0; color: #66fcf1; }\n        .companeros-section .intro-companeros { color: #c5c6c7; line-height: 1.6; max-width: 60ch; }\n        .ventajas-cuenta { color: #dfe3e8; line-height: 1.8; padding-left: 20px; }\n        .tarjeta-cuenta { background: #1f2833; border-radius: 16px; padding: 24px; border-top: 4px solid #e5b340; }\n        .pestanas-cuenta { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; background: #0b0c10; padding: 5px; border-radius: 26px; margin-bottom: 18px; }\n        .pestanas-cuenta button { background: transparent; color: #c5c6c7; border: none; padding: 9px; border-radius: 22px; cursor: pointer; font-weight: bold; font-size: 0.95rem; }\n        .pestanas-cuenta button[aria-selected=\"true\"] { background: #e5b340; color: #0b0c10; }\n        .form-cuenta { display: flex; flex-direction: column; gap: 8px; }\n        .form-cuenta[hidden] { display: none; }\n        .form-cuenta input { padding: 11px; border-radius: 6px; border: 1px solid #45a29e; background: #0b0c10; color: white; font-size: 1rem; box-sizing: border-box; width: 100%; }\n        .campo-clave { position: relative; }\n        .campo-clave input { padding-right: 70px; }\n        .campo-clave button { position: absolute; right: 6px; top: 50%; transform: translateY(-50%); background: none; border: none; color: #66fcf1; cursor: pointer; font-size: 0.85rem; padding: 6px; }\n        .form-cuenta > button[type=\"submit\"], .btn-cerrar-sesion { background: #e5b340; color: #0b0c10; border: none; padding: 12px; font-weight: bold; cursor: pointer; border-radius: 8px; font-size: 1rem; margin-top: 6px; }\n        .form-cuenta > button[type=\"submit\"]:disabled { opacity: 0.6; cursor: wait; }\n        .estado-cuenta { min-height: 1.2em; margin: 0; font-size: 0.9rem; color: #c5c6c7; }\n        .estado-cuenta.error { color: #ff8a80; }\n        .estado-cuenta.exito { color: #66fcf1; }\n        .sesion-activa h3 { margin: 0 0 4px 0; font-size: 1.4rem; }\n        .sesion-activa .usuario-sesion { color: #8b95a1; margin: 0 0 16px 0; }\n        .lista-miembros { list-style: none; padding: 0; margin: 10px 0 18px 0; max-height: 260px; overflow-y: auto; display: flex; flex-direction: column; gap: 6px; }\n        .lista-miembros li { background: #0b0c10; border-radius: 8px; padding: 8px 12px; display: flex; justify-content: space-between; gap: 10px; font-size: 0.92rem; }\n        .lista-miembros span { color: #8b95a1; }\n        .btn-cerrar-sesion { width: 100%; background: transparent; color: #e5b340; border: 1px solid #e5b340; }\n        .cuenta-menu { color: #e5b340; font-size: 0.9rem; margin-left: 12px; white-space: nowrap; text-decoration: none; }\n\n        /* ===================== BITÁCORA: ACTIVIDADES Y AUTOR ===================== */\n        .columna-galeria { min-width: 0; }\n        .filtros-actividad { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 16px; }\n        .filtros-actividad button { background: rgba(31, 40, 51, 0.85); color: #c5c6c7; border: 1px solid #2e3b4a; padding: 7px 13px; border-radius: 18px; cursor: pointer; font-size: 0.88rem; }\n        .filtros-actividad button[aria-pressed=\"true\"] { background: #66fcf1; color: #0b0c10; border-color: #66fcf1; font-weight: bold; }\n        .etiqueta-actividad { display: inline-block; margin-top: 8px; background: rgba(229, 179, 64, 0.15); color: #f1dca6; border-radius: 12px; padding: 3px 10px; font-size: 0.78rem; }\n        .item-media .autor-media { margin: 6px 0 0 0; color: #c5c6c7; font-size: 0.85rem; }\n        .publicar-como { margin: 0; color: #e5b340; font-size: 0.88rem; }\n        .btn-entrar { background-color: #66fcf1; color: #0b0c10; border: none; padding: 12px 30px; font-size: 1.1rem; font-weight: bold; border-radius: 25px; cursor: pointer; margin-top: 15px; }\n\n        /* VISOR DEL LOGO */\n        #visor-logo { position: fixed; inset: 0; background: rgba(0, 0, 0, 0.92); backdrop-filter: blur(8px); display: none; align-items: center; justify-content: center; z-index: 1100; padding: 20px; box-sizing: border-box; }\n        #visor-logo.abierto { display: flex; animation: aparecer 0.3s ease; }\n        #visor-logo img { max-width: 100%; max-height: 90vh; border-radius: 12px; border: 2px solid #e5b340; box-shadow: 0 0 40px rgba(229, 179, 64, 0.4); }\n\n        /* VISOR DEL TELESCOPIO: ocular circular con retícula que \"enfoca\" al integrante */\n        #visor-telescopio { position: fixed; inset: 0; background: radial-gradient(circle at center, rgba(5, 8, 20, 0.9) 0%, rgba(0, 0, 0, 0.97) 70%); backdrop-filter: blur(8px); display: none; align-items: center; justify-content: center; z-index: 1100; padding: 20px; box-sizing: border-box; }\n        #visor-telescopio.abierto { display: flex; animation: aparecer 0.3s ease; }\n        .telescopio-escena { display: flex; align-items: center; justify-content: center; gap: 30px; flex-wrap: wrap; max-width: 1000px; }\n        .telescopio-svg { width: 260px; height: 260px; flex-shrink: 0; }\n        .telescopio-svg .tubo-grande { transform-origin: 90px 150px; animation: apuntar 1s ease-out; }\n        @keyframes apuntar { from { transform: rotate(18deg); } to { transform: rotate(0deg); } }\n        .ocular-bloque { display: flex; flex-direction: column; align-items: center; text-align: center; }\n        .ocular { position: relative; width: min(380px, 78vw); aspect-ratio: 1; border-radius: 50%; overflow: hidden; border: 6px solid #e5b340; box-shadow: 0 0 0 10px #1f2833, 0 0 0 12px #45a29e, 0 0 60px rgba(102, 252, 241, 0.45); background: #000; }\n        .ocular img { width: 100%; height: 100%; object-fit: cover; object-position: center top; transform-origin: center top; display: block; }\n        /* Enfoque: la imagen pasa de borrosa y lejana a nítida */\n        .ocular img.enfocando { animation: enfocar 1.1s ease-out forwards; }\n        @keyframes enfocar { 0% { filter: blur(14px) brightness(0.4); transform: scale(1.8); } 70% { filter: blur(2px) brightness(0.95); } 100% { filter: blur(0) brightness(1); transform: scale(1.22); } }\n        .ocular .reticula { position: absolute; inset: 0; pointer-events: none; background:\n            radial-gradient(circle, transparent 55%, rgba(0, 0, 0, 0.75) 100%),\n            linear-gradient(to right, transparent calc(50% - 0.5px), rgba(102, 252, 241, 0.55) calc(50% - 0.5px), rgba(102, 252, 241, 0.55) calc(50% + 0.5px), transparent calc(50% + 0.5px)),\n            linear-gradient(to bottom, transparent calc(50% - 0.5px), rgba(102, 252, 241, 0.55) calc(50% - 0.5px), rgba(102, 252, 241, 0.55) calc(50% + 0.5px), transparent calc(50% + 0.5px)); }\n        .ocular .reticula::after { content: ''; position: absolute; inset: 30%; border: 1px dashed rgba(102, 252, 241, 0.5); border-radius: 50%; }\n        .ocular-estado { color: #66fcf1; font-size: 0.85rem; letter-spacing: 3px; margin: 18px 0 4px 0; text-transform: uppercase; min-height: 1.2em; }\n        .ocular-nombre { color: #fff; font-size: 2rem; margin: 0; text-shadow: 0 0 15px rgba(102, 252, 241, 0.5); }\n        .ocular-rol { color: #e5b340; font-weight: bold; font-size: 1.1rem; margin: 6px 0 0 0; }\n        .controles-telescopio { display: flex; gap: 12px; margin-top: 20px; flex-wrap: wrap; justify-content: center; }\n        .controles-telescopio button, .cerrar-visor { background: #1f2833; color: #66fcf1; border: 1px solid #66fcf1; padding: 10px 18px; border-radius: 25px; cursor: pointer; font-size: 1rem; font-weight: bold; transition: background 0.2s ease, color 0.2s ease; }\n        .controles-telescopio button:hover, .cerrar-visor:hover { background: #66fcf1; color: #0b0c10; }\n        .cerrar-visor { position: absolute; top: 20px; right: 20px; width: 46px; height: 46px; padding: 0; font-size: 1.4rem; }\n        @keyframes aparecer { from { opacity: 0; } to { opacity: 1; } }\n\n        @media (max-width: 1100px) {\n            .historia-contenido, .companeros-contenido { grid-template-columns: minmax(0, 1fr); }\n            .tarjeta-qr { max-width: 340px; }\n            .menu-sitio { margin-left: 16px; }\n            .menu-sitio a { padding: 8px 9px; font-size: 0.9rem; }\n        }\n        @media (max-width: 900px) {\n            .menu-sitio { display: none; }\n            .cuerpo-guia { grid-template-columns: minmax(0, 1fr); }\n            .guia-armado { padding: 18px; }\n            .bitacora-contenido { grid-template-columns: minmax(0, 1fr); }\n            .form-multimedia { position: static; }\n            .telescopio3d-contenido { grid-template-columns: 1fr; }\n            .escenario3d { height: 400px; --escala3d: 0.8; }\n            /* En pantallas angostas la constelación pasa a cuadrícula para que los íconos no se encimen */\n            .constelacion { aspect-ratio: auto; display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 30px 10px; }\n            .lineas-constelacion { display: none; }\n            .nodo-integrante { position: static; transform: none; width: auto; }\n            /* La figura del cielo pasa arriba del panel para no taparlo */\n            .cielo-profundo { flex-direction: column; }\n            .figura-cielo { position: relative; right: auto; top: auto; transform: none; width: min(420px, 100%); margin: 0 auto 10px auto; }\n            .panel-cielo { margin-left: 0; }\n        }\n        @media (max-width: 700px) {\n            .telescopio-svg { width: 140px; height: 140px; }\n            .ocular-nombre { font-size: 1.5rem; }\n            .hero-emblema { width: 120px; height: 120px; }\n            /* En celular se navega la guía con Anterior/Siguiente para no alargar la página */\n            .indice-pasos { display: none; }\n            .pie-contenido { flex-direction: column; text-align: center; }\n            .escenario3d { height: 320px; --escala3d: 0.6; }\n            .navbar { padding: 12px 16px; }\n            .navbar h1 { font-size: 1.1rem; }\n            .btn-pantalla { font-size: 0.8rem; padding: 6px 10px; }\n            .icono-integrante { width: 88px; height: 88px; }\n            .cielo-profundo { padding: 40px 16px 160px 16px; }\n            .panel-cielo { padding: 20px; }\n        }\n        @media (prefers-reduced-motion: reduce) {\n            html { scroll-behavior: auto; }\n            .ocular img.enfocando, .telescopio-svg .tubo-grande, .tube, .lens, .nebulosa { animation: none; }\n            .ocular img.enfocando { transform: scale(1.22); }\n            .constelacion.visible line, .constelacion.visible .nodo-integrante, .cielo-profundo, .figura-cielo .figura, .figura-cielo .trazo, .figura-cielo .etiqueta-fig { transition: none; }\n        }\n    </style>\n</head>\n<body>\n    <canvas id=\"cielo-estrellado\" aria-hidden=\"true\"></canvas>\n\n    <div id=\"modal-bienvenida\">\n        <div class=\"modal-content modal-equipo\">\n            <img src=\"equipo-observatorio.jpg\" alt=\"El equipo del Observatorio Estelar UNAD | CIP Turbo\">\n            <h2>¡Bienvenidos al Observatorio Estelar!</h2>\n            <p>Somos el equipo de la UNAD y el CIP Turbo. Explora nuestro telescopio, conoce su historia y comparte con nosotros cada actividad del proyecto.</p>\n            <button class=\"btn-entrar\" onclick=\"cerrarModal()\">Comenzar exploración</button>\n        </div>\n    </div>\n    \n    <nav class=\"navbar\">\n        <button type=\"button\" class=\"logo-circulo\" onclick=\"abrirLogo()\" aria-label=\"Ver logo del Observatorio Estelar\" title=\"Ver logo\"></button>\n        <h1>UNAD | CIP TURBO</h1>\n        <ul class=\"menu-sitio\" aria-label=\"Secciones del sitio\">\n            <li><a href=\"#telescopio\">Telescopio</a></li>\n            <li><a href=\"#historia\">Historia</a></li>\n            <li><a href=\"#equipo\">Equipo</a></li>\n            <li><a href=\"#cielo-profundo\">Cielo profundo</a></li>\n            <li><a href=\"#bitacora\">Bitácora</a></li>\n            <li><a href=\"#companeros\" id=\"enlace-cuenta\">Ingresar</a></li>\n        </ul>\n        <button type=\"button\" class=\"btn-pantalla\" id=\"btn-pantalla\" onclick=\"alternarPantallaCompleta()\">⛶ Pantalla completa</button>\n    </nav>\n    \n    <header class=\"hero-section\" id=\"inicio\">\n        <div class=\"hero-emblema\" role=\"img\" aria-label=\"Emblema del Observatorio Estelar UNAD CIP Turbo\"></div>\n        <h1 class=\"titulo-principal\">OBSERVATORIO ESTELAR</h1>\n        <p class=\"hero-lema\">Explora, Aprende, Descubre - Fundado en 2026</p>\n        <div class=\"hero-acciones\">\n            <a class=\"accion-principal\" href=\"#telescopio\">Ver el telescopio</a>\n            <a class=\"accion-secundaria\" href=\"#equipo\">Conocer al equipo</a>\n            <a class=\"accion-secundaria\" href=\"#companeros\">Mi cuenta</a>\n        </div>\n    </header>\n    \n    <section class=\"comienzo-section\">\n        <h2 style=\"color: #e5b340;\">Nuestro Primer Comienzo</h2>\n        <div class=\"explicacion-container\">\n            <button type=\"button\" class=\"animacion-telescopio\" onclick=\"abrirTelescopio(0)\" aria-label=\"Observar al equipo con el telescopio\" title=\"¡Haz clic para observar!\">\n                <svg viewBox=\"0 0 100 100\">\n                    <rect x=\"20\" y=\"40\" width=\"60\" height=\"15\" fill=\"#e5b340\" class=\"tube\" />\n                    <polygon points=\"80,35 80,60 95,55 95,40\" fill=\"#333\" class=\"lens\" />\n                    <line x1=\"40\" y1=\"55\" x2=\"30\" y2=\"90\" stroke=\"#c5c6c7\" stroke-width=\"4\" />\n                    <line x1=\"50\" y1=\"55\" x2=\"50\" y2=\"90\" stroke=\"#c5c6c7\" stroke-width=\"4\" />\n                    <line x1=\"60\" y1=\"55\" x2=\"70\" y2=\"90\" stroke=\"#c5c6c7\" stroke-width=\"4\" />\n                </svg>\n            </button>\n            <div class=\"texto-explicacion\">\n                <p>Todo gran viaje comienza aquí. Con nuestro telescopio apuntando a las estrellas, buscamos llevar el conocimiento del universo a la comunidad.</p>\n                <p class=\"pista-observar\">🔭 <strong>Haz clic en el telescopio</strong> o en cualquier integrante para observarlo.</p>\n            </div>\n        </div>\n    </section>\n    \n    <!-- Telescopio refractor en 3D: se construye con CSS desde JS (sin librerías) -->\n    <section class=\"telescopio3d-section\" id=\"telescopio\">\n        <div class=\"telescopio3d-contenido\">\n            <div class=\"escenario3d\" id=\"escenario3d\" tabindex=\"0\" role=\"group\" aria-label=\"Modelo 3D del telescopio refractor. Arrastra o usa las flechas izquierda y derecha para girarlo.\">\n                <div class=\"sombra-suelo\"></div>\n                <div class=\"modelo3d\" id=\"modelo3d\"></div>\n                <p class=\"pista-giro\">Arrastra para girar el telescopio</p>\n            </div>\n            <div>\n                <h2>Nuestro telescopio refractor</h2>\n                <p class=\"telescopio3d-intro\">Un refractor usa una lente al frente, llamada objetivo, para reunir la luz de objetos lejanos. Esa luz viaja por el tubo y forma una imagen que el ocular amplía para nuestro ojo. Da imágenes nítidas y con buen contraste de la Luna, los planetas y las estrellas dobles, y casi no necesita mantenimiento.</p>\n                <ul class=\"lista-partes\" id=\"lista-partes\" aria-label=\"Partes del telescopio\"></ul>\n                <div class=\"detalle-parte\" id=\"detalle-parte\" aria-live=\"polite\">\n                    <h3 id=\"detalle-titulo\"></h3>\n                    <p id=\"detalle-texto\"></p>\n                </div>\n            </div>\n        </div>\n\n        <!-- Guía de armado: pasos para distintos tipos de telescopio -->\n        <div class=\"guia-armado\" id=\"guia-armado\">\n            <h3>Guía de armado paso a paso</h3>\n            <p>Elige el tipo de telescopio y sigue los pasos. Marca cada paso cuando lo termines para ayudar a otros compañeros a armarlo.</p>\n            <div class=\"aviso-sol\" role=\"note\">⚠️ <span>Nunca apuntes el telescopio ni el buscador hacia el Sol sin un filtro solar certificado: puede causar ceguera permanente en segundos.</span></div>\n            <div class=\"pestanas-guia\" id=\"pestanas-guia\" role=\"tablist\" aria-label=\"Tipos de telescopio\"></div>\n            <div class=\"cuerpo-guia\">\n                <ol class=\"indice-pasos\" id=\"indice-pasos\" aria-label=\"Lista de pasos\"></ol>\n                <div class=\"paso-actual\" id=\"paso-actual\" aria-live=\"polite\">\n                    <div class=\"barra-avance\" aria-hidden=\"true\"><span id=\"barra-avance-guia\" style=\"width: 0%;\"></span></div>\n                    <p class=\"contador-paso\" id=\"contador-paso\"></p>\n                    <h4 id=\"titulo-paso\"></h4>\n                    <p class=\"texto-paso\" id=\"texto-paso\"></p>\n                    <p class=\"consejo-paso\" id=\"consejo-paso\"></p>\n                    <div class=\"controles-paso\">\n                        <button type=\"button\" id=\"btn-paso-anterior\" onclick=\"moverPaso(-1)\">◀ Anterior</button>\n                        <button type=\"button\" id=\"btn-paso-siguiente\" onclick=\"moverPaso(1)\">Siguiente ▶</button>\n                        <label><input type=\"checkbox\" id=\"check-paso\" onchange=\"marcarPaso(this.checked)\"> Paso hecho</label>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </section>\n\n    <!-- Historia del telescopio: el QR lleva a la página completa de historia -->\n    <section class=\"historia-section\" id=\"historia\">\n        <div class=\"historia-contenido\">\n            <div>\n                <h2>Historia del telescopio</h2>\n                <p>Desde las primeras lentes holandesas hasta el telescopio espacial James Webb: más de 400 años mirando el cielo. Escanea el código QR con la cámara del celular para leer la historia completa, incluida la de nuestro propio observatorio.</p>\n                <ul class=\"hitos-resumen\">\n                    <li><strong>1608</strong> Lippershey</li>\n                    <li><strong>1609</strong> Galileo</li>\n                    <li><strong>1668</strong> Newton</li>\n                    <li><strong>1803</strong> Observatorio de Bogotá</li>\n                    <li><strong>1990</strong> Hubble</li>\n                    <li><strong>2021</strong> James Webb</li>\n                    <li><strong>2026</strong> Nuestro observatorio</li>\n                </ul>\n                <div class=\"acciones-historia\">\n                    <a class=\"accion-principal\" id=\"enlace-historia\" href=\"historia-telescopio.html\">Leer la historia</a>\n                    <button type=\"button\" class=\"accion-secundaria\" id=\"btn-descargar-qr\" onclick=\"descargarQR()\">Descargar QR para imprimir</button>\n                </div>\n            </div>\n            <div class=\"tarjeta-qr\">\n                <canvas id=\"lienzo-qr\" width=\"250\" height=\"250\" role=\"img\" aria-label=\"Código QR hacia la historia del telescopio\"></canvas>\n                <p class=\"qr-no-disponible\" id=\"qr-no-disponible\" hidden>El código QR se crea con la dirección real del sitio cuando la página esté publicada en internet.</p>\n                <strong>Escanea y descubre</strong>\n                <small id=\"url-qr\"></small>\n            </div>\n        </div>\n    </section>\n\n    <!-- Constelación del equipo: cada integrante es una estrella; clic abre el telescopio -->\n    <section class=\"equipo-section\" id=\"equipo\">\n        <h2>Estructura del Proyecto</h2>\n        <p class=\"pista-observar\">Haz clic en cada integrante para <strong>observarlo con el telescopio</strong>.</p>\n        <ul class=\"leyenda-roles\" aria-label=\"Color según el rol\">\n            <li style=\"--color-rol: #a66bff;\">Directores</li>\n            <li style=\"--color-rol: #e5b340;\">Liderazgo</li>\n            <li style=\"--color-rol: #66fcf1;\">Desarrollo web</li>\n            <li style=\"--color-rol: #45a29e;\">Investigadores</li>\n        </ul>\n        <div class=\"constelacion\" id=\"constelacion\">\n            <svg class=\"lineas-constelacion\" viewBox=\"0 0 1000 620\" aria-hidden=\"true\">\n                <line x1=\"330\" y1=\"90\" x2=\"670\" y2=\"90\" />\n                <line x1=\"330\" y1=\"90\" x2=\"390\" y2=\"300\" />\n                <line x1=\"670\" y1=\"90\" x2=\"610\" y2=\"300\" />\n                <line x1=\"390\" y1=\"300\" x2=\"610\" y2=\"300\" />\n                <line x1=\"390\" y1=\"300\" x2=\"170\" y2=\"500\" />\n                <line x1=\"390\" y1=\"300\" x2=\"500\" y2=\"530\" />\n                <line x1=\"610\" y1=\"300\" x2=\"500\" y2=\"530\" />\n                <line x1=\"610\" y1=\"300\" x2=\"830\" y2=\"500\" />\n                <circle cx=\"500\" cy=\"190\" r=\"1.8\" /><circle cx=\"250\" cy=\"300\" r=\"1.2\" /><circle cx=\"760\" cy=\"280\" r=\"1.5\" />\n                <circle cx=\"120\" cy=\"120\" r=\"1.2\" /><circle cx=\"900\" cy=\"160\" r=\"1.8\" /><circle cx=\"300\" cy=\"590\" r=\"1.3\" />\n                <circle cx=\"700\" cy=\"600\" r=\"1.2\" /><circle cx=\"960\" cy=\"420\" r=\"1.4\" /><circle cx=\"40\" cy=\"380\" r=\"1.6\" />\n            </svg>\n            <button type=\"button\" class=\"nodo-integrante nodo-director\" style=\"--x: 33%; --y: 14.52%; --orden: 0;\" data-foto=\"Gemini_Generated_Image_hmxjazhmxjazhmxj.jpg\">\n                <span class=\"icono-integrante\"><img src=\"Gemini_Generated_Image_hmxjazhmxjazhmxj.jpg\" alt=\"\"></span>\n                <span class=\"nodo-nombre\">Prof. Yesid</span>\n                <span class=\"nodo-rol\">Director del Proyecto</span>\n            </button>\n            <button type=\"button\" class=\"nodo-integrante nodo-director\" style=\"--x: 67%; --y: 14.52%; --orden: 1;\" data-foto=\"Gemini_Generated_Image_hmxjazhmxjazhmxj%20(1).jpg\">\n                <span class=\"icono-integrante\"><img src=\"Gemini_Generated_Image_hmxjazhmxjazhmxj%20(1).jpg\" alt=\"\"></span>\n                <span class=\"nodo-nombre\">Prof. Clemente</span>\n                <span class=\"nodo-rol\">Director Académico</span>\n            </button>\n            <button type=\"button\" class=\"nodo-integrante nodo-lider\" style=\"--x: 39%; --y: 48.39%; --orden: 2;\" data-foto=\"xd.jpg\">\n                <span class=\"icono-integrante\"><img src=\"xd.jpg\" alt=\"\"></span>\n                <span class=\"nodo-nombre\">Taliana</span>\n                <span class=\"nodo-rol\">Líder del Observatorio</span>\n            </button>\n            <button type=\"button\" class=\"nodo-integrante nodo-creador\" style=\"--x: 61%; --y: 48.39%; --orden: 3;\" data-foto=\"Gemin.jpg\">\n                <span class=\"icono-integrante\"><img src=\"Gemin.jpg\" alt=\"\"></span>\n                <span class=\"nodo-nombre\">Adrián</span>\n                <span class=\"nodo-rol\">Creador de la Web</span>\n            </button>\n            <button type=\"button\" class=\"nodo-integrante nodo-investigador\" style=\"--x: 17%; --y: 80.65%; --orden: 4;\" data-foto=\"ChatGPT%20Image%2024%20sept%202026%2C%2002_57_11%20p.m.png\">\n                <span class=\"icono-integrante\"><img src=\"ChatGPT%20Image%2024%20sept%202026%2C%2002_57_11%20p.m.png\" alt=\"\"></span>\n                <span class=\"nodo-nombre\">Moisés</span>\n                <span class=\"nodo-rol\">Investigador</span>\n            </button>\n            <button type=\"button\" class=\"nodo-integrante nodo-investigador\" style=\"--x: 50%; --y: 85.48%; --orden: 5;\" data-foto=\"cv.jpg\">\n                <span class=\"icono-integrante\"><img src=\"cv.jpg\" alt=\"\"></span>\n                <span class=\"nodo-nombre\">Yilessa</span>\n                <span class=\"nodo-rol\">Investigadora</span>\n            </button>\n            <button type=\"button\" class=\"nodo-integrante nodo-investigador\" style=\"--x: 83%; --y: 80.65%; --orden: 6;\" data-foto=\"sistem.jpg\">\n                <span class=\"icono-integrante\"><img src=\"sistem.jpg\" alt=\"\"></span>\n                <span class=\"nodo-nombre\">Didier</span>\n                <span class=\"nodo-rol\">Investigador</span>\n            </button>\n        </div>\n    </section>\n\n    <!-- Cielo profundo: ilustración con colores que cambian según el objeto elegido -->\n    <section class=\"cielo-profundo\" id=\"cielo-profundo\">\n        <div class=\"nebulosa\" aria-hidden=\"true\"></div>\n        <span class=\"astro\" style=\"left: 50%; top: 10%;\" aria-hidden=\"true\"></span>\n        <span class=\"astro grande\" style=\"left: 95%; top: 9%;\" aria-hidden=\"true\"></span>\n\n        <!-- Figuras ilustradas: una por objeto; JS activa la que corresponde al botón elegido -->\n        <svg class=\"figura-cielo\" id=\"figura-cielo\" viewBox=\"0 0 500 500\" role=\"img\" aria-label=\"Ilustración de la Nebulosa de Orión\">\n            <defs>\n                <filter id=\"fx-blur-grande\" x=\"-50%\" y=\"-50%\" width=\"200%\" height=\"200%\"><feGaussianBlur stdDeviation=\"22\" /></filter>\n                <filter id=\"fx-blur-medio\" x=\"-50%\" y=\"-50%\" width=\"200%\" height=\"200%\"><feGaussianBlur stdDeviation=\"9\" /></filter>\n                <filter id=\"fx-blur-fino\" x=\"-50%\" y=\"-50%\" width=\"200%\" height=\"200%\"><feGaussianBlur stdDeviation=\"3\" /></filter>\n                <filter id=\"fx-brillo\" x=\"-200%\" y=\"-200%\" width=\"500%\" height=\"500%\">\n                    <feGaussianBlur stdDeviation=\"3\" result=\"halo\" />\n                    <feMerge><feMergeNode in=\"halo\" /><feMergeNode in=\"halo\" /><feMergeNode in=\"SourceGraphic\" /></feMerge>\n                </filter>\n                <linearGradient id=\"grad-pilar\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n                    <stop offset=\"0\" stop-color=\"#3b1b24\" />\n                    <stop offset=\"0.35\" stop-color=\"#1b0d15\" />\n                    <stop offset=\"1\" stop-color=\"#06040a\" />\n                </linearGradient>\n                <g id=\"destello-estrella\" class=\"destello\"><line x1=\"-16\" y1=\"0\" x2=\"16\" y2=\"0\" /><line x1=\"0\" y1=\"-16\" x2=\"0\" y2=\"16\" /></g>\n            </defs>\n\n            <!-- ORIÓN: la constelación del cazador con la nebulosa M42 en su espada -->\n            <g class=\"figura\" data-figura=\"orion\">\n                <ellipse cx=\"258\" cy=\"332\" rx=\"70\" ry=\"52\" fill=\"var(--c1)\" opacity=\"0.55\" filter=\"url(#fx-blur-grande)\" />\n                <ellipse cx=\"262\" cy=\"328\" rx=\"36\" ry=\"26\" fill=\"var(--c2)\" opacity=\"0.8\" filter=\"url(#fx-blur-medio)\" />\n                <path d=\"M225 330 C 240 300, 280 305, 292 322 C 300 340, 275 360, 250 352\" stroke=\"var(--c1)\" stroke-width=\"10\" fill=\"none\" opacity=\"0.7\" filter=\"url(#fx-blur-fino)\" />\n                <ellipse cx=\"258\" cy=\"330\" rx=\"9\" ry=\"7\" fill=\"#fff\" opacity=\"0.9\" filter=\"url(#fx-blur-fino)\" />\n                <path class=\"trazo\" d=\"M245 60 L160 120 L205 270 L250 258 L295 246 L330 135 L245 60\" />\n                <path class=\"trazo\" d=\"M205 270 L190 430\" />\n                <path class=\"trazo\" d=\"M295 246 L345 420\" />\n                <g filter=\"url(#fx-brillo)\">\n                    <circle cx=\"245\" cy=\"60\" r=\"3.5\" fill=\"#dfe8ff\" />\n                    <circle cx=\"160\" cy=\"120\" r=\"7\" fill=\"#ffae70\" />\n                    <circle cx=\"330\" cy=\"135\" r=\"4.5\" fill=\"#dfe8ff\" />\n                    <circle cx=\"205\" cy=\"270\" r=\"4.5\" fill=\"#d6e4ff\" />\n                    <circle cx=\"250\" cy=\"258\" r=\"4.5\" fill=\"#d6e4ff\" />\n                    <circle cx=\"295\" cy=\"246\" r=\"4\" fill=\"#d6e4ff\" />\n                    <circle cx=\"190\" cy=\"430\" r=\"4.5\" fill=\"#dfe8ff\" />\n                    <circle cx=\"345\" cy=\"420\" r=\"7\" fill=\"#b9d2ff\" />\n                    <circle cx=\"255\" cy=\"302\" r=\"2\" fill=\"#fff\" />\n                    <circle cx=\"260\" cy=\"360\" r=\"2\" fill=\"#fff\" />\n                </g>\n                <use href=\"#destello-estrella\" x=\"160\" y=\"120\" />\n                <use href=\"#destello-estrella\" x=\"345\" y=\"420\" />\n                <text class=\"etiqueta-fig\" x=\"148\" y=\"104\" text-anchor=\"end\">Betelgeuse</text>\n                <text class=\"etiqueta-fig\" x=\"360\" y=\"448\">Rigel</text>\n                <text class=\"etiqueta-fig\" x=\"250\" y=\"236\" text-anchor=\"middle\">Cinturón de Orión</text>\n                <text class=\"etiqueta-fig\" x=\"302\" y=\"336\">M42</text>\n            </g>\n\n            <!-- VÍA LÁCTEA: la galaxia vista desde afuera, con la posición del Sol -->\n            <g class=\"figura\" data-figura=\"vialactea\">\n                <g id=\"brazos-galaxia\">\n                    <path d=\"M250 250 C 300 200, 380 230, 390 300 C 400 380, 320 430, 240 420 C 160 410, 110 350, 120 280\" stroke=\"var(--c2)\" stroke-width=\"44\" fill=\"none\" opacity=\"0.45\" filter=\"url(#fx-blur-medio)\" />\n                    <path d=\"M250 250 C 300 200, 380 230, 390 300 C 400 380, 320 430, 240 420 C 160 410, 110 350, 120 280\" stroke=\"var(--c3)\" stroke-width=\"10\" fill=\"none\" opacity=\"0.6\" filter=\"url(#fx-blur-fino)\" />\n                    <path d=\"M250 250 C 300 200, 380 230, 390 300 C 400 380, 320 430, 240 420 C 160 410, 110 350, 120 280\" stroke=\"var(--c2)\" stroke-width=\"44\" fill=\"none\" opacity=\"0.45\" filter=\"url(#fx-blur-medio)\" transform=\"rotate(180 250 250)\" />\n                    <path d=\"M250 250 C 300 200, 380 230, 390 300 C 400 380, 320 430, 240 420 C 160 410, 110 350, 120 280\" stroke=\"var(--c3)\" stroke-width=\"10\" fill=\"none\" opacity=\"0.6\" filter=\"url(#fx-blur-fino)\" transform=\"rotate(180 250 250)\" />\n                    <path d=\"M250 250 C 290 215, 350 235, 355 290 C 360 345, 300 375, 250 365\" stroke=\"var(--c3)\" stroke-width=\"6\" fill=\"none\" opacity=\"0.35\" filter=\"url(#fx-blur-fino)\" transform=\"rotate(90 250 250)\" />\n                    <path d=\"M250 250 C 290 215, 350 235, 355 290 C 360 345, 300 375, 250 365\" stroke=\"var(--c3)\" stroke-width=\"6\" fill=\"none\" opacity=\"0.35\" filter=\"url(#fx-blur-fino)\" transform=\"rotate(270 250 250)\" />\n                </g>\n                <ellipse cx=\"250\" cy=\"250\" rx=\"90\" ry=\"26\" fill=\"var(--c1)\" opacity=\"0.6\" filter=\"url(#fx-blur-medio)\" transform=\"rotate(-25 250 250)\" />\n                <ellipse cx=\"250\" cy=\"250\" rx=\"55\" ry=\"45\" fill=\"var(--c1)\" opacity=\"0.85\" filter=\"url(#fx-blur-medio)\" />\n                <ellipse cx=\"250\" cy=\"250\" rx=\"18\" ry=\"15\" fill=\"#fff\" opacity=\"0.9\" filter=\"url(#fx-blur-fino)\" />\n                <g fill=\"#fff\" opacity=\"0.85\">\n                    <circle cx=\"330\" cy=\"215\" r=\"1.4\" /><circle cx=\"372\" cy=\"262\" r=\"1.2\" /><circle cx=\"360\" cy=\"370\" r=\"1.5\" /><circle cx=\"300\" cy=\"410\" r=\"1.1\" />\n                    <circle cx=\"200\" cy=\"405\" r=\"1.4\" /><circle cx=\"140\" cy=\"330\" r=\"1.2\" /><circle cx=\"170\" cy=\"285\" r=\"1\" /><circle cx=\"130\" cy=\"240\" r=\"1.3\" />\n                    <circle cx=\"160\" cy=\"130\" r=\"1.2\" /><circle cx=\"230\" cy=\"92\" r=\"1.4\" /><circle cx=\"310\" cy=\"85\" r=\"1\" /><circle cx=\"370\" cy=\"160\" r=\"1.2\" />\n                    <circle cx=\"265\" cy=\"150\" r=\"1\" /><circle cx=\"215\" cy=\"330\" r=\"1.1\" /><circle cx=\"110\" cy=\"190\" r=\"1\" /><circle cx=\"395\" cy=\"330\" r=\"1.2\" />\n                </g>\n                <circle cx=\"388\" cy=\"310\" r=\"5\" fill=\"#ffe27a\" filter=\"url(#fx-brillo)\" />\n                <circle class=\"trazo\" cx=\"388\" cy=\"310\" r=\"13\" />\n                <path class=\"trazo\" d=\"M398 320 L 425 350\" />\n                <text class=\"etiqueta-fig\" x=\"430\" y=\"368\" text-anchor=\"middle\">El Sol</text>\n                <text class=\"etiqueta-fig\" x=\"430\" y=\"386\" text-anchor=\"middle\">(estamos aquí)</text>\n                <text class=\"etiqueta-fig\" x=\"250\" y=\"205\" text-anchor=\"middle\">Centro galáctico</text>\n            </g>\n\n            <!-- CARINA: pilares de polvo iluminados y la estrella Eta Carinae con sus dos lóbulos -->\n            <g class=\"figura\" data-figura=\"carina\">\n                <ellipse cx=\"230\" cy=\"280\" rx=\"190\" ry=\"130\" fill=\"var(--c1)\" opacity=\"0.5\" filter=\"url(#fx-blur-grande)\" />\n                <ellipse cx=\"330\" cy=\"200\" rx=\"120\" ry=\"85\" fill=\"var(--c2)\" opacity=\"0.55\" filter=\"url(#fx-blur-grande)\" />\n                <ellipse cx=\"160\" cy=\"170\" rx=\"90\" ry=\"70\" fill=\"var(--c3)\" opacity=\"0.45\" filter=\"url(#fx-blur-grande)\" />\n                <!-- Borde luminoso: la luz de las estrellas jóvenes ilumina la punta de cada pilar -->\n                <g fill=\"none\" stroke=\"var(--c1)\" stroke-width=\"7\" opacity=\"0.7\" filter=\"url(#fx-blur-fino)\">\n                    <path d=\"M40 500 C 58 450, 66 410, 84 378 C 96 356, 90 334, 104 318 C 110 300, 118 292, 124 280 C 132 292, 128 306, 138 318 C 150 334, 142 350, 156 372 C 172 400, 180 450, 205 500\" />\n                    <path d=\"M215 500 C 228 452, 240 414, 256 386 C 266 366, 262 346, 276 330 C 284 318, 290 312, 298 308 C 306 318, 304 330, 314 344 C 322 360, 316 378, 326 398 C 340 436, 346 470, 362 500\" />\n                    <path d=\"M372 500 C 386 468, 394 440, 408 420 C 414 412, 418 406, 422 404 C 430 414, 436 440, 446 462 C 452 478, 456 490, 462 500\" />\n                </g>\n                <g fill=\"url(#grad-pilar)\">\n                    <path d=\"M40 500 C 58 450, 66 410, 84 378 C 96 356, 90 334, 104 318 C 110 300, 118 292, 124 280 C 132 292, 128 306, 138 318 C 150 334, 142 350, 156 372 C 172 400, 180 450, 205 500 Z\" />\n                    <path d=\"M215 500 C 228 452, 240 414, 256 386 C 266 366, 262 346, 276 330 C 284 318, 290 312, 298 308 C 306 318, 304 330, 314 344 C 322 360, 316 378, 326 398 C 340 436, 346 470, 362 500 Z\" />\n                    <path d=\"M372 500 C 386 468, 394 440, 408 420 C 414 412, 418 406, 422 404 C 430 414, 436 440, 446 462 C 452 478, 456 490, 462 500 Z\" />\n                </g>\n                <g fill=\"var(--c1)\" opacity=\"0.75\" filter=\"url(#fx-blur-medio)\">\n                    <ellipse cx=\"124\" cy=\"282\" rx=\"10\" ry=\"16\" /><ellipse cx=\"298\" cy=\"310\" rx=\"10\" ry=\"16\" /><ellipse cx=\"422\" cy=\"406\" rx=\"8\" ry=\"12\" />\n                </g>\n                <ellipse cx=\"310\" cy=\"132\" rx=\"28\" ry=\"15\" fill=\"var(--c1)\" opacity=\"0.9\" filter=\"url(#fx-blur-fino)\" transform=\"rotate(-40 310 132)\" />\n                <ellipse cx=\"350\" cy=\"166\" rx=\"28\" ry=\"15\" fill=\"var(--c1)\" opacity=\"0.9\" filter=\"url(#fx-blur-fino)\" transform=\"rotate(-40 350 166)\" />\n                <circle cx=\"330\" cy=\"149\" r=\"5.5\" fill=\"#fff\" filter=\"url(#fx-brillo)\" />\n                <use href=\"#destello-estrella\" x=\"330\" y=\"149\" />\n                <g fill=\"#fff\" filter=\"url(#fx-brillo)\">\n                    <circle cx=\"120\" cy=\"90\" r=\"2\" /><circle cx=\"420\" cy=\"80\" r=\"2.5\" /><circle cx=\"230\" cy=\"190\" r=\"1.8\" /><circle cx=\"440\" cy=\"300\" r=\"2\" /><circle cx=\"70\" cy=\"250\" r=\"1.6\" />\n                </g>\n                <path class=\"trazo\" d=\"M345 135 L 395 95\" />\n                <text class=\"etiqueta-fig\" x=\"400\" y=\"88\">Eta Carinae</text>\n                <text class=\"etiqueta-fig\" x=\"255\" y=\"300\" text-anchor=\"middle\">Pilares de polvo</text>\n            </g>\n\n            <!-- PLÉYADES: las siete hermanas envueltas en polvo que refleja su luz azul -->\n            <g class=\"figura\" data-figura=\"pleyades\">\n                <g stroke=\"var(--c3)\" stroke-width=\"14\" fill=\"none\" opacity=\"0.28\" filter=\"url(#fx-blur-medio)\">\n                    <path d=\"M110 150 L 300 320\" /><path d=\"M160 110 L 360 290\" /><path d=\"M200 230 L 390 380\" /><path d=\"M90 230 L 250 360\" />\n                </g>\n                <ellipse cx=\"255\" cy=\"215\" rx=\"170\" ry=\"120\" fill=\"var(--c2)\" opacity=\"0.35\" filter=\"url(#fx-blur-grande)\" />\n                <path class=\"trazo\" d=\"M140 215 L 185 265 L 265 255 L 375 270 L 380 232 M 265 255 L 195 165 L 225 115\" stroke-dasharray=\"4 6\" />\n                <g filter=\"url(#fx-brillo)\">\n                    <circle cx=\"265\" cy=\"255\" r=\"7.5\" fill=\"#d6e8ff\" />\n                    <circle cx=\"375\" cy=\"270\" r=\"6\" fill=\"#d6e8ff\" />\n                    <circle cx=\"380\" cy=\"232\" r=\"4\" fill=\"#d6e8ff\" />\n                    <circle cx=\"140\" cy=\"215\" r=\"6\" fill=\"#d6e8ff\" />\n                    <circle cx=\"195\" cy=\"165\" r=\"5.5\" fill=\"#d6e8ff\" />\n                    <circle cx=\"225\" cy=\"115\" r=\"5\" fill=\"#d6e8ff\" />\n                    <circle cx=\"185\" cy=\"265\" r=\"5.5\" fill=\"#d6e8ff\" />\n                    <circle cx=\"120\" cy=\"170\" r=\"3\" fill=\"#d6e8ff\" />\n                    <circle cx=\"215\" cy=\"85\" r=\"2.5\" fill=\"#d6e8ff\" />\n                </g>\n                <use href=\"#destello-estrella\" x=\"265\" y=\"255\" />\n                <use href=\"#destello-estrella\" x=\"375\" y=\"270\" />\n                <use href=\"#destello-estrella\" x=\"140\" y=\"215\" />\n                <text class=\"etiqueta-fig\" x=\"265\" y=\"285\" text-anchor=\"middle\">Alcíone</text>\n                <text class=\"etiqueta-fig\" x=\"392\" y=\"298\" text-anchor=\"middle\">Atlas</text>\n                <text class=\"etiqueta-fig\" x=\"392\" y=\"222\">Pléione</text>\n                <text class=\"etiqueta-fig\" x=\"126\" y=\"240\" text-anchor=\"end\">Electra</text>\n                <text class=\"etiqueta-fig\" x=\"182\" y=\"160\" text-anchor=\"end\">Maia</text>\n                <text class=\"etiqueta-fig\" x=\"240\" y=\"110\">Taígeta</text>\n                <text class=\"etiqueta-fig\" x=\"185\" y=\"295\" text-anchor=\"middle\">Mérope</text>\n            </g>\n        </svg>\n        <!-- Horizonte de Turbo: mar del golfo de Urabá, palmeras y la cúpula del observatorio -->\n        <svg class=\"horizonte-turbo\" viewBox=\"0 0 1440 200\" preserveAspectRatio=\"xMidYMax slice\" aria-hidden=\"true\">\n            <rect x=\"0\" y=\"150\" width=\"1440\" height=\"50\" fill=\"#050914\" />\n            <g stroke=\"var(--c1)\" stroke-opacity=\"0.35\" stroke-width=\"2\" stroke-linecap=\"round\">\n                <line x1=\"980\" y1=\"162\" x2=\"1060\" y2=\"162\" /><line x1=\"1010\" y1=\"172\" x2=\"1090\" y2=\"172\" /><line x1=\"960\" y1=\"182\" x2=\"1020\" y2=\"182\" />\n                <line x1=\"420\" y1=\"166\" x2=\"470\" y2=\"166\" /><line x1=\"700\" y1=\"178\" x2=\"760\" y2=\"178\" />\n            </g>\n            <path d=\"M0 152 C 90 128, 190 126, 300 142 C 360 150, 420 150, 470 150 L 0 150 Z\" fill=\"#03050b\" />\n            <path d=\"M1040 150 C 1100 126, 1200 118, 1300 124 C 1370 128, 1410 136, 1440 138 L 1440 150 Z\" fill=\"#03050b\" />\n            <!-- Cúpula del observatorio con la ranura abierta -->\n            <rect x=\"1150\" y=\"102\" width=\"130\" height=\"48\" fill=\"#02030a\" />\n            <path d=\"M1155 102 A 60 60 0 0 1 1275 102 Z\" fill=\"#02030a\" />\n            <path d=\"M1208 46 L 1222 46 L 1224 102 L 1206 102 Z\" fill=\"var(--c1)\" fill-opacity=\"0.55\" />\n            <line x1=\"1215\" y1=\"80\" x2=\"1250\" y2=\"40\" stroke=\"#02030a\" stroke-width=\"9\" stroke-linecap=\"round\" />\n            <rect x=\"1180\" y=\"120\" width=\"14\" height=\"30\" fill=\"var(--c3)\" fill-opacity=\"0.35\" />\n            <!-- Palmeras -->\n            <g fill=\"none\" stroke=\"#02030a\" stroke-linecap=\"round\">\n                <path d=\"M110 152 Q 104 110 128 64\" stroke-width=\"7\" />\n                <path d=\"M128 64 Q 90 50 62 70\" stroke-width=\"5\" /><path d=\"M128 64 Q 110 30 80 28\" stroke-width=\"5\" />\n                <path d=\"M128 64 Q 150 26 186 34\" stroke-width=\"5\" /><path d=\"M128 64 Q 170 56 190 84\" stroke-width=\"5\" />\n                <path d=\"M128 64 Q 128 36 140 18\" stroke-width=\"4\" />\n                <path d=\"M220 152 Q 226 120 212 92\" stroke-width=\"6\" />\n                <path d=\"M212 92 Q 186 80 170 96\" stroke-width=\"4\" /><path d=\"M212 92 Q 204 66 184 62\" stroke-width=\"4\" />\n                <path d=\"M212 92 Q 236 70 258 78\" stroke-width=\"4\" /><path d=\"M212 92 Q 244 94 252 112\" stroke-width=\"4\" />\n            </g>\n        </svg>\n        <div class=\"panel-cielo\">\n            <h2>Cielo profundo</h2>\n            <p class=\"subtitulo-cielo\">Elige un objeto y el cielo cambia a sus colores.</p>\n            <div class=\"temas-cielo\" id=\"temas-cielo\" role=\"group\" aria-label=\"Objetos del cielo profundo\"></div>\n            <div class=\"objeto-cielo\" aria-live=\"polite\">\n                <figure class=\"foto-real\">\n                    <img id=\"cielo-foto\" src=\"img-cielo/orion-m42.jpg\" alt=\"\">\n                    <figcaption id=\"cielo-credito\"></figcaption>\n                </figure>\n                <h3 id=\"cielo-nombre\"></h3>\n                <p id=\"cielo-texto\"></p>\n                <p class=\"cuando-verlo\"><strong>Cuándo verlo desde Turbo:</strong> <span id=\"cielo-cuando\"></span></p>\n            </div>\n        </div>\n    </section>\n    \n    <section class=\"bitacora-section\" id=\"bitacora\">\n        <h2 style=\"color: #66fcf1;\">Bitácora Multimedia</h2>\n        <p>Añade imágenes o videos para la presentación.</p>\n        <p class=\"modo-bitacora\" id=\"modo-bitacora\" role=\"status\"></p>\n        <div class=\"bitacora-contenido\">\n        <form class=\"form-multimedia\" onsubmit=\"agregarMedia(event)\">\n            <label class=\"etiqueta-campo\" for=\"media-titulo\">Título</label>\n            <input type=\"text\" id=\"media-titulo\" placeholder=\"Ej: Primera noche de observación\" maxlength=\"100\" required>\n            <label class=\"etiqueta-campo\" for=\"media-actividad\">Actividad</label>\n            <select id=\"media-actividad\" required></select>\n            <div id=\"campo-autor\">\n                <label class=\"etiqueta-campo\" for=\"media-autor\">Tu nombre (opcional)</label>\n                <input type=\"text\" id=\"media-autor\" maxlength=\"40\" placeholder=\"Así se verá quién aportó\">\n            </div>\n            <p class=\"publicar-como\" id=\"publicar-como\" hidden></p>\n            <label class=\"etiqueta-campo\" for=\"media-tipo\">Tipo</label>\n            <select id=\"media-tipo\" onchange=\"actualizarCamposBitacora()\">\n                <option value=\"imagen\">Imagen</option>\n                <option value=\"video\">Video (MP4 o WEBM)</option>\n                <option value=\"youtube\">Video de YouTube (enlace)</option>\n            </select>\n            <div id=\"campo-archivo\" hidden>\n                <label class=\"etiqueta-campo\" for=\"media-archivo\">Archivo</label>\n                <input type=\"file\" id=\"media-archivo\">\n                <small class=\"ayuda-campo\" id=\"ayuda-archivo\"></small>\n            </div>\n            <div id=\"campo-url\">\n                <label class=\"etiqueta-campo\" for=\"media-url\" id=\"etiqueta-url\">Enlace o nombre del archivo</label>\n                <input type=\"text\" id=\"media-url\" placeholder=\"Ej: foto1.jpg, mi_video.mp4 o URL\">\n            </div>\n            <progress id=\"progreso-subida\" max=\"100\" value=\"0\" hidden></progress>\n            <p class=\"estado-bitacora\" id=\"estado-bitacora\" aria-live=\"polite\"></p>\n            <button type=\"submit\" id=\"btn-subir\">Añadir a la Bitácora</button>\n        </form>\n        <div class=\"columna-galeria\">\n            <div class=\"filtros-actividad\" id=\"filtros-actividad\" role=\"group\" aria-label=\"Filtrar por actividad\"></div>\n            <div class=\"galeria-bitacora\" id=\"contenedor-media\"></div>\n        </div>\n        </div>\n    </section>\n\n    <!-- Compañeros del proyecto: registro e ingreso con usuario y contraseña -->\n    <section class=\"companeros-section\" id=\"companeros\">\n        <div class=\"companeros-contenido\">\n            <div>\n                <h2>Compañeros del proyecto</h2>\n                <p class=\"intro-companeros\">Estás dentro del Observatorio Estelar con tu cuenta. Con ella:</p>\n                <ul class=\"ventajas-cuenta\">\n                    <li>Tus fotos y videos en la bitácora llevan tu nombre verificado.</li>\n                    <li>Ves la lista de compañeros registrados en el proyecto.</li>\n                    <li>Tu sesión queda abierta en tu celular durante 30 días.</li>\n                </ul>\n                <p class=\"modo-bitacora\" id=\"aviso-cuentas\" hidden></p>\n            </div>\n            <div class=\"tarjeta-cuenta\" id=\"tarjeta-cuenta\">\n                <div id=\"bloque-acceso\">\n                    <div class=\"pestanas-cuenta\" role=\"tablist\" aria-label=\"Acceso\">\n                        <button type=\"button\" role=\"tab\" id=\"pestana-ingresar\" aria-selected=\"true\" onclick=\"mostrarFormularioCuenta('ingresar')\">Iniciar sesión</button>\n                        <button type=\"button\" role=\"tab\" id=\"pestana-registrar\" aria-selected=\"false\" onclick=\"mostrarFormularioCuenta('registrar')\">Crear cuenta</button>\n                    </div>\n                    <form class=\"form-cuenta\" id=\"form-ingresar\" onsubmit=\"enviarCuenta(event, 'iniciar')\">\n                        <label class=\"etiqueta-campo\" for=\"ingreso-usuario\">Usuario</label>\n                        <input type=\"text\" id=\"ingreso-usuario\" autocomplete=\"username\" autocapitalize=\"none\" required>\n                        <label class=\"etiqueta-campo\" for=\"ingreso-clave\">Contraseña</label>\n                        <div class=\"campo-clave\">\n                            <input type=\"password\" id=\"ingreso-clave\" autocomplete=\"current-password\" required>\n                            <button type=\"button\" onclick=\"alternarClave('ingreso-clave', this)\">Mostrar</button>\n                        </div>\n                        <p class=\"estado-cuenta\" id=\"estado-ingresar\" aria-live=\"polite\"></p>\n                        <button type=\"submit\">Iniciar sesión</button>\n                    </form>\n                    <form class=\"form-cuenta\" id=\"form-registrar\" onsubmit=\"enviarCuenta(event, 'registrar')\" hidden>\n                        <label class=\"etiqueta-campo\" for=\"registro-nombre\">Nombre completo</label>\n                        <input type=\"text\" id=\"registro-nombre\" autocomplete=\"name\" maxlength=\"60\" required>\n                        <label class=\"etiqueta-campo\" for=\"registro-usuario\">Usuario</label>\n                        <input type=\"text\" id=\"registro-usuario\" autocomplete=\"username\" autocapitalize=\"none\" maxlength=\"20\" pattern=\"[A-Za-z0-9._]{3,20}\" title=\"De 3 a 20 caracteres: letras sin tilde, números, punto o guion bajo\" required>\n                        <small class=\"ayuda-campo\">De 3 a 20 caracteres: letras sin tilde, números, punto o guion bajo.</small>\n                        <label class=\"etiqueta-campo\" for=\"registro-clave\">Contraseña</label>\n                        <div class=\"campo-clave\">\n                            <input type=\"password\" id=\"registro-clave\" autocomplete=\"new-password\" minlength=\"8\" maxlength=\"72\" required>\n                            <button type=\"button\" onclick=\"alternarClave('registro-clave', this)\">Mostrar</button>\n                        </div>\n                        <label class=\"etiqueta-campo\" for=\"registro-clave2\">Repite la contraseña</label>\n                        <input type=\"password\" id=\"registro-clave2\" autocomplete=\"new-password\" minlength=\"8\" maxlength=\"72\" required>\n                        <small class=\"ayuda-campo\">Mínimo 8 caracteres.</small>\n                        <p class=\"estado-cuenta\" id=\"estado-registrar\" aria-live=\"polite\"></p>\n                        <button type=\"submit\">Crear cuenta</button>\n                    </form>\n                </div>\n                <div class=\"sesion-activa\" id=\"bloque-sesion\" hidden>\n                    <h3 id=\"saludo-sesion\"></h3>\n                    <p class=\"usuario-sesion\" id=\"usuario-sesion\"></p>\n                    <strong>Compañeros registrados</strong>\n                    <ul class=\"lista-miembros\" id=\"lista-miembros\"></ul>\n                    <button type=\"button\" class=\"btn-cerrar-sesion\" onclick=\"cerrarSesion()\">Cerrar sesión</button>\n                </div>\n            </div>\n        </div>\n    </section>\n\n    <footer class=\"pie-sitio\">\n        <div class=\"pie-contenido\">\n            <div class=\"pie-marca\">\n                <span class=\"pie-logo\" aria-hidden=\"true\"></span>\n                <div>\n                    <strong>Observatorio Estelar</strong>\n                    UNAD | CIP Turbo · Turbo, Antioquia · Fundado en 2026\n                </div>\n            </div>\n            <p>Sitio creado por Adrián · Fotos del cielo: NASA, ESA y ESO (ver créditos en cada foto)</p>\n            <a href=\"#inicio\">Volver arriba</a>\n        </div>\n    </footer>\n\n    <!-- Visor del logo completo -->\n    <div id=\"visor-logo\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Logo del Observatorio Estelar\" onclick=\"cerrarLogo()\">\n        <button type=\"button\" class=\"cerrar-visor\" onclick=\"cerrarLogo()\" aria-label=\"Cerrar\">✕</button>\n        <img src=\"logo.jpg\" alt=\"Logo UNAD CIP Turbo - Observatorio Estelar, fundado en 2026\" onclick=\"event.stopPropagation()\">\n    </div>\n\n    <!-- Visor del telescopio: muestra al integrante seleccionado a través del ocular -->\n    <div id=\"visor-telescopio\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Observación con telescopio\">\n        <button type=\"button\" class=\"cerrar-visor\" onclick=\"cerrarTelescopio()\" aria-label=\"Cerrar telescopio\">✕</button>\n        <div class=\"telescopio-escena\">\n            <svg class=\"telescopio-svg\" viewBox=\"0 0 260 260\" aria-hidden=\"true\">\n                <g class=\"tubo-grande\">\n                    <rect x=\"40\" y=\"120\" width=\"170\" height=\"36\" rx=\"6\" fill=\"#e5b340\" transform=\"rotate(-20 125 138)\" />\n                    <rect x=\"190\" y=\"104\" width=\"34\" height=\"50\" rx=\"4\" fill=\"#c79a2e\" transform=\"rotate(-20 125 138)\" />\n                    <rect x=\"28\" y=\"126\" width=\"18\" height=\"24\" rx=\"3\" fill=\"#333\" transform=\"rotate(-20 125 138)\" />\n                    <circle cx=\"228\" cy=\"92\" r=\"9\" fill=\"#66fcf1\" opacity=\"0.8\" />\n                </g>\n                <circle cx=\"115\" cy=\"160\" r=\"8\" fill=\"#c5c6c7\" />\n                <line x1=\"115\" y1=\"165\" x2=\"75\" y2=\"245\" stroke=\"#c5c6c7\" stroke-width=\"6\" stroke-linecap=\"round\" />\n                <line x1=\"115\" y1=\"165\" x2=\"115\" y2=\"248\" stroke=\"#c5c6c7\" stroke-width=\"6\" stroke-linecap=\"round\" />\n                <line x1=\"115\" y1=\"165\" x2=\"155\" y2=\"245\" stroke=\"#c5c6c7\" stroke-width=\"6\" stroke-linecap=\"round\" />\n            </svg>\n            <div class=\"ocular-bloque\">\n                <div class=\"ocular\">\n                    <img id=\"ocular-imagen\" src=\"\" alt=\"\">\n                    <div class=\"reticula\"></div>\n                </div>\n                <p class=\"ocular-estado\" id=\"ocular-estado\">Enfocando…</p>\n                <h3 class=\"ocular-nombre\" id=\"ocular-nombre\"></h3>\n                <p class=\"ocular-rol\" id=\"ocular-rol\"></p>\n                <div class=\"controles-telescopio\">\n                    <button type=\"button\" onclick=\"moverTelescopio(-1)\" aria-label=\"Integrante anterior\">◀ Anterior</button>\n                    <button type=\"button\" id=\"btn-voz\" onclick=\"alternarVoz()\" aria-pressed=\"true\">🔊 Voz activada</button>\n                    <button type=\"button\" onclick=\"moverTelescopio(1)\" aria-label=\"Integrante siguiente\">Siguiente ▶</button>\n                </div>\n            </div>\n        </div>\n    </div>\n\n    <!-- qrcode-generator 1.4.4 (Kazuhiko Arase, licencia MIT), copia local para funcionar sin CDN -->\n    <script src=\"js/qrcode.min.js\"></script>\n    <script>\n        function cerrarModal() { \n            document.getElementById('modal-bienvenida').style.display = 'none'; \n        }\n        \n        /* ===================== BITÁCORA MULTIMEDIA ===================== */\n        // Modo \"nube\": la página está publicada en Hostinger y todo se guarda en el servidor (visible para todos).\n        // Modo \"local\": la página se abrió desde el PC; se usa el guardado del navegador como antes.\n        const API_BITACORA = '/api/bitacora.php';\n        const CLAVE_LOCAL = 'bitacoraObservatorioPreview';\n        let modoBitacora = 'local';\n        // Límites de tamaño en MB; el servidor informa los reales del hosting al cargar la bitácora\n        let limitesMB = { imagen: 10, video: 50 };\n        // En Vercel los archivos van directo del navegador a Vercel Blob (el servidor lo indica al cargar)\n        let subidaDirecta = false;\n\n        function leerLocal() {\n            try { return JSON.parse(localStorage.getItem(CLAVE_LOCAL)) || []; } catch (e) { return []; }\n        }\n        function guardarLocal(datos) {\n            try { localStorage.setItem(CLAVE_LOCAL, JSON.stringify(datos)); } catch (e) { mostrarEstado('Tu navegador no permite guardar datos locales.', 'error'); }\n        }\n\n        function mostrarEstado(texto, clase = '') {\n            const estado = document.getElementById('estado-bitacora');\n            estado.textContent = texto;\n            estado.className = 'estado-bitacora' + (clase ? ' ' + clase : '');\n        }\n\n        // Muestra solo los campos que aplican según el modo y el tipo elegido\n        function actualizarCamposBitacora() {\n            const tipo = document.getElementById('media-tipo').value;\n            const usaArchivo = modoBitacora === 'nube' && tipo !== 'youtube';\n            const archivo = document.getElementById('media-archivo');\n            const url = document.getElementById('media-url');\n            document.getElementById('campo-archivo').hidden = !usaArchivo;\n            document.getElementById('campo-url').hidden = usaArchivo;\n            archivo.required = usaArchivo;\n            url.required = !usaArchivo;\n            archivo.accept = tipo === 'video' ? 'video/mp4,video/webm' : 'image/jpeg,image/png,image/webp,image/gif';\n            document.getElementById('ayuda-archivo').textContent = tipo === 'video'\n                ? `MP4 o WEBM, máximo ${limitesMB.video} MB. Para videos más pesados usa un enlace de YouTube.`\n                : `JPG, PNG, WEBP o GIF, máximo ${limitesMB.imagen} MB.`;\n            if (tipo === 'youtube') {\n                document.getElementById('etiqueta-url').textContent = 'Enlace de YouTube';\n                url.placeholder = 'Ej: https://youtu.be/abc123XYZ00';\n            } else {\n                document.getElementById('etiqueta-url').textContent = 'Enlace o nombre del archivo';\n                url.placeholder = 'Ej: foto1.jpg, mi_video.mp4 o URL';\n            }\n        }\n\n        // Convierte cualquier enlace de YouTube (watch, youtu.be, shorts) en enlace embebible\n        function enlaceEmbedYoutube(url) {\n            const coincidencia = String(url).match(/(?:youtube\\.com\\/(?:watch\\?(?:.*&)?v=|embed\\/|shorts\\/|live\\/)|youtube-nocookie\\.com\\/embed\\/|youtu\\.be\\/)([A-Za-z0-9_-]{11})/);\n            return coincidencia ? `https://www.youtube-nocookie.com/embed/${coincidencia[1]}` : null;\n        }\n\n        // Actividades del proyecto (misma lista que valida el servidor en api/bitacora.php)\n        const ACTIVIDADES = {\n            observacion: 'Observación nocturna',\n            taller: 'Taller o clase',\n            montaje: 'Montaje y mantenimiento',\n            salida: 'Salida de campo',\n            divulgacion: 'Charla o divulgación',\n            reunion: 'Reunión del equipo',\n            otra: 'Otra actividad'\n        };\n        let publicacionesBitacora = [];\n        let filtroActividad = 'todas';\n\n        function prepararActividades() {\n            const selector = document.getElementById('media-actividad');\n            Object.entries(ACTIVIDADES).forEach(([clave, nombre]) => {\n                const opcion = document.createElement('option');\n                opcion.value = clave;\n                opcion.textContent = nombre;\n                selector.appendChild(opcion);\n            });\n        }\n\n        // Botones de filtro con el número de publicaciones de cada actividad\n        function dibujarFiltros() {\n            const contenedor = document.getElementById('filtros-actividad');\n            contenedor.innerHTML = '';\n            const conteo = {};\n            publicacionesBitacora.forEach(item => { const a = item.actividad || 'otra'; conteo[a] = (conteo[a] || 0) + 1; });\n            const opciones = [['todas', 'Todas', publicacionesBitacora.length]]\n                .concat(Object.entries(ACTIVIDADES).filter(([clave]) => conteo[clave]).map(([clave, nombre]) => [clave, nombre, conteo[clave]]));\n            if (!conteo[filtroActividad] && filtroActividad !== 'todas') filtroActividad = 'todas';\n            opciones.forEach(([clave, nombre, total]) => {\n                const boton = document.createElement('button');\n                boton.type = 'button';\n                boton.textContent = `${nombre} (${total})`;\n                boton.setAttribute('aria-pressed', String(clave === filtroActividad));\n                boton.addEventListener('click', () => { filtroActividad = clave; dibujarGaleria(publicacionesBitacora); });\n                contenedor.appendChild(boton);\n            });\n        }\n\n        // Dibuja la galería con textContent y atributos: el título nunca se interpreta como HTML\n        function dibujarGaleria(items) {\n            publicacionesBitacora = items;\n            dibujarFiltros();\n            const contenedor = document.getElementById('contenedor-media');\n            contenedor.innerHTML = '';\n            const visibles = filtroActividad === 'todas' ? items : items.filter(item => (item.actividad || 'otra') === filtroActividad);\n            if (!visibles.length) {\n                const vacio = document.createElement('p');\n                vacio.className = 'galeria-vacia';\n                vacio.textContent = 'Todavía no hay publicaciones. Sube la primera foto o video de una actividad del observatorio.';\n                contenedor.appendChild(vacio);\n                return;\n            }\n            visibles.forEach(item => {\n                const div = document.createElement('div');\n                div.className = 'item-media';\n                let medio;\n                if (item.tipo === 'imagen') {\n                    medio = document.createElement('img');\n                    medio.src = item.url;\n                    medio.alt = item.titulo;\n                    medio.loading = 'lazy';\n                    medio.onerror = () => { medio.onerror = null; medio.src = 'https://placehold.co/600x400?text=Error+al+cargar+imagen'; };\n                } else if (item.tipo === 'video') {\n                    medio = document.createElement('video');\n                    medio.controls = true;\n                    medio.preload = 'metadata';\n                    medio.src = item.url;\n                } else {\n                    medio = document.createElement('iframe');\n                    medio.src = enlaceEmbedYoutube(item.url) || 'about:blank';\n                    medio.title = item.titulo;\n                    medio.allowFullscreen = true;\n                    medio.setAttribute('frameborder', '0');\n                    medio.setAttribute('allow', 'accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture');\n                }\n                const titulo = document.createElement('h4');\n                titulo.textContent = item.titulo;\n                const actividad = document.createElement('span');\n                actividad.className = 'etiqueta-actividad';\n                actividad.textContent = ACTIVIDADES[item.actividad] || ACTIVIDADES.otra;\n                div.append(medio, titulo, actividad);\n                if (item.autor) {\n                    const autor = document.createElement('p');\n                    autor.className = 'autor-media';\n                    autor.textContent = `Aportado por ${item.autor}${item.verificado ? ' ✔' : ''}`;\n                    if (item.verificado) autor.title = 'Compañero con cuenta en el proyecto';\n                    div.appendChild(autor);\n                }\n                if (item.fecha) {\n                    const fecha = document.createElement('p');\n                    fecha.className = 'fecha-media';\n                    fecha.textContent = new Date(item.fecha).toLocaleString('es-CO', { dateStyle: 'medium', timeStyle: 'short' });\n                    div.appendChild(fecha);\n                }\n                const borrar = document.createElement('button');\n                borrar.type = 'button';\n                borrar.className = 'btn-borrar';\n                borrar.textContent = 'Borrar';\n                borrar.addEventListener('click', () => borrarMedia(item.id, item.titulo));\n                div.appendChild(borrar);\n                contenedor.appendChild(div);\n            });\n        }\n\n        async function cargarMedia() {\n            const aviso = document.getElementById('modo-bitacora');\n            if (location.protocol !== 'file:') {\n                try {\n                    const controlador = new AbortController();\n                    const tiempo = setTimeout(() => controlador.abort(), 8000);\n                    const respuesta = await fetch(API_BITACORA, { cache: 'no-store', signal: controlador.signal });\n                    clearTimeout(tiempo);\n                    if (respuesta.status === 401) { location.replace('./'); return; }\n                    const datos = await respuesta.json();\n                    if (!respuesta.ok || !datos.ok) throw new Error(datos.error || 'Respuesta no válida');\n                    modoBitacora = 'nube';\n                    aviso.textContent = '🌐 Bitácora compartida: lo que subas aquí lo ven todos los compañeros del proyecto.';\n                    aviso.className = 'modo-bitacora nube';\n                    actualizarCamposBitacora();\n                    subidaDirecta = !!datos.subidaDirecta;\n                    if (datos.limites) {\n                        limitesMB = {\n                            imagen: Math.floor((datos.limites.imagen / 1048576) * 10) / 10,\n                            video: Math.floor((datos.limites.video / 1048576) * 10) / 10\n                        };\n                        actualizarCamposBitacora();\n                    }\n                    dibujarGaleria(datos.items);\n                    return;\n                } catch (e) {\n                    // Sin servidor PHP disponible: se usa el modo local\n                }\n            }\n            modoBitacora = 'local';\n            // El aviso distingue entre abrir el archivo en el PC y una publicación sin servidor PHP (ej. Netlify)\n            aviso.textContent = location.protocol === 'file:'\n                ? '💻 Modo local: estás viendo la página desde tu PC, así que lo que agregues solo se guarda en este navegador. Al publicarla en Hostinger se vuelve compartida.'\n                : '📱 Bitácora personal: lo que agregues se guarda solo en este dispositivo y no lo verán otras personas.';\n            aviso.className = 'modo-bitacora';\n            actualizarCamposBitacora();\n            dibujarGaleria(leerLocal());\n        }\n\n        // Envía el formulario mostrando el progreso (fetch no informa el avance de subida)\n        function enviarAlServidor(formulario) {\n            return new Promise((resolver, rechazar) => {\n                const peticion = new XMLHttpRequest();\n                const barra = document.getElementById('progreso-subida');\n                peticion.open('POST', API_BITACORA);\n                peticion.upload.onprogress = (e) => {\n                    if (e.lengthComputable) { barra.hidden = false; barra.value = Math.round((e.loaded / e.total) * 100); }\n                };\n                peticion.onload = () => {\n                    barra.hidden = true;\n                    let datos = {};\n                    // Algunos hostings anteponen avisos HTML de PHP; se lee solo la parte JSON de la respuesta\n                    const texto = peticion.responseText || '';\n                    const inicio = texto.indexOf('{\"ok\"');\n                    try { datos = JSON.parse(inicio >= 0 ? texto.slice(inicio) : texto); } catch (e) { /* respuesta no JSON */ }\n                    if (peticion.status === 413 && !datos.error) datos.error = 'El archivo es más grande de lo que permite el servidor. Redúcelo o súbelo a YouTube y comparte el enlace.';\n                    if (peticion.status === 401) { location.replace('./'); return; }\n                    if (peticion.status >= 200 && peticion.status < 300 && datos.ok) resolver(datos);\n                    else rechazar(new Error(datos.error || `El servidor respondió con error ${peticion.status}.`));\n                };\n                peticion.onerror = () => { barra.hidden = true; rechazar(new Error('Sin conexión con el servidor. Revisa tu internet e inténtalo de nuevo.')); };\n                peticion.send(formulario);\n            });\n        }\n\n        async function agregarMedia(event) {\n            event.preventDefault();\n            const titulo = document.getElementById('media-titulo').value.trim();\n            const tipo = document.getElementById('media-tipo').value;\n            const url = document.getElementById('media-url').value.trim();\n            const boton = document.getElementById('btn-subir');\n\n            if (tipo === 'youtube' && !enlaceEmbedYoutube(url)) {\n                mostrarEstado('Ese enlace no es de un video de YouTube. Cópialo desde el botón \"Compartir\" de YouTube.', 'error');\n                return;\n            }\n\n            if (modoBitacora === 'local') {\n                const datos = leerLocal();\n                const autorLocal = document.getElementById('media-autor').value.trim();\n                datos.unshift({ id: Date.now(), titulo, tipo, url, actividad: document.getElementById('media-actividad').value, autor: autorLocal || 'Visitante', fecha: new Date().toISOString() });\n                guardarLocal(datos);\n                document.getElementById('media-titulo').value = '';\n                document.getElementById('media-url').value = '';\n                mostrarEstado('Guardado en este navegador.', 'exito');\n                dibujarGaleria(datos);\n                return;\n            }\n\n            const formulario = new FormData();\n            formulario.append('accion', 'subir');\n            formulario.append('titulo', titulo);\n            formulario.append('tipo', tipo);\n            formulario.append('actividad', document.getElementById('media-actividad').value);\n            formulario.append('autor', document.getElementById('media-autor').value.trim());\n            let archivoElegido = null;\n            if (tipo === 'youtube') {\n                formulario.append('url', url);\n            } else {\n                const archivo = document.getElementById('media-archivo').files[0];\n                archivoElegido = archivo;\n                if (!archivo) { mostrarEstado('Elige un archivo para subir.', 'error'); return; }\n                const limite = limitesMB[tipo];\n                if (archivo.size > limite * 1024 * 1024) {\n                    mostrarEstado(`El archivo pesa más de ${limite} MB, el máximo que permite el servidor. Redúcelo o súbelo a YouTube y comparte el enlace.`, 'error');\n                    return;\n                }\n                if (!subidaDirecta) formulario.append('archivo', archivo);\n            }\n\n            boton.disabled = true;\n            boton.textContent = 'Subiendo…';\n            mostrarEstado('Subiendo a la bitácora compartida…');\n            try {\n                if (subidaDirecta && archivoElegido) {\n                    // Vercel: primero el archivo va a Vercel Blob y luego se registra la publicación\n                    const direccion = await subirArchivoDirecto(archivoElegido, tipo);\n                    formulario.set('accion', 'publicar');\n                    formulario.append('url', direccion);\n                }\n                await enviarAlServidor(formulario);\n                document.getElementById('media-titulo').value = '';\n                document.getElementById('media-url').value = '';\n                document.getElementById('media-archivo').value = '';\n                await cargarMedia();\n                mostrarEstado('Publicado. Ya lo ven todos los compañeros.', 'exito');\n            } catch (error) {\n                mostrarEstado(error.message, 'error');\n            } finally {\n                boton.disabled = false;\n                boton.textContent = 'Añadir a la Bitácora';\n            }\n        }\n\n        // Sube el archivo directo a Vercel Blob mostrando el avance; el servidor solo autoriza la subida\n        async function subirArchivoDirecto(archivo, tipo) {\n            const { upload } = await import('./js/blob-cliente.js');\n            const barra = document.getElementById('progreso-subida');\n            const extension = (archivo.name.split('.').pop() || '').toLowerCase().replace(/[^a-z0-9]/g, '').slice(0, 5) || 'bin';\n            barra.hidden = false;\n            barra.value = 0;\n            try {\n                const resultado = await upload(`bitacora/${tipo}.${extension}`, archivo, {\n                    access: 'public',\n                    handleUploadUrl: 'api/subida',\n                    clientPayload: tipo,\n                    contentType: archivo.type,\n                    onUploadProgress: (avance) => { barra.value = Math.round(avance.percentage); },\n                });\n                return resultado.url;\n            } catch (error) {\n                const mensaje = String(error && error.message || '');\n                if (/content type|contentType/i.test(mensaje)) throw new Error('Formato no permitido. Sube imágenes JPG, PNG, WEBP o GIF, o videos MP4 o WEBM.');\n                if (/size|large|maximum/i.test(mensaje)) throw new Error(`El archivo supera el tamaño permitido (${limitesMB[tipo]} MB).`);\n                if (/401|sesión/i.test(mensaje)) { location.replace('./'); throw new Error('Tu sesión terminó.'); }\n                throw new Error('No se pudo subir el archivo. Revisa tu conexión e inténtalo de nuevo.');\n            } finally {\n                barra.hidden = true;\n            }\n        }\n\n        async function borrarMedia(id, titulo) {\n            if (!confirm(`¿Borrar \"${titulo}\" de la bitácora?` + (modoBitacora === 'nube' ? ' Se quitará para todos los compañeros.' : ''))) return;\n            if (modoBitacora === 'local') {\n                const datos = leerLocal().filter(item => item.id !== id);\n                guardarLocal(datos);\n                dibujarGaleria(datos);\n                return;\n            }\n            const formulario = new FormData();\n            formulario.append('accion', 'borrar');\n            formulario.append('id', id);\n            try {\n                await enviarAlServidor(formulario);\n                await cargarMedia();\n                mostrarEstado('Publicación borrada.', 'exito');\n            } catch (error) {\n                mostrarEstado(error.message, 'error');\n            }\n        }\n\n        window.onload = cargarMedia;\n\n        /* ===================== PANTALLA COMPLETA ===================== */\n        // Expande toda la página (Chrome, Opera, Edge, Firefox); Esc o el mismo botón la restauran\n        function alternarPantallaCompleta() {\n            if (!document.fullscreenElement) {\n                document.documentElement.requestFullscreen().catch(() => alert('Tu navegador bloqueó la pantalla completa. Presiona F11.'));\n            } else {\n                document.exitFullscreen();\n            }\n        }\n        document.addEventListener('fullscreenchange', () => {\n            document.getElementById('btn-pantalla').textContent = document.fullscreenElement ? '✕ Salir de pantalla completa' : '⛶ Pantalla completa';\n        });\n\n        /* ===================== LOGO ===================== */\n        function abrirLogo() { document.getElementById('visor-logo').classList.add('abierto'); }\n        function cerrarLogo() { document.getElementById('visor-logo').classList.remove('abierto'); }\n\n        /* ===================== TELESCOPIO ===================== */\n        // Los integrantes se leen de las tarjetas: el nombre y rol que se muestran/anuncian son siempre los de la página\n        let integrantes = [];\n        let indiceActual = 0;\n        let temporizadorEnfoque = null;\n        let vozActiva = true;\n        try { vozActiva = localStorage.getItem('observatorioVoz') !== 'off'; } catch (e) { /* almacenamiento bloqueado: se usa el valor por defecto */ }\n\n        // Los nodos de la constelación son botones: mouse, teclado y lector de pantalla funcionan sin código extra\n        function prepararIntegrantes() {\n            const nodos = document.querySelectorAll('#constelacion .nodo-integrante');\n            integrantes = Array.from(nodos).map((nodo, i) => {\n                const nombre = nodo.querySelector('.nodo-nombre').textContent.trim();\n                const rol = nodo.querySelector('.nodo-rol').textContent.trim();\n                nodo.setAttribute('aria-label', `Observar a ${nombre}, ${rol}`);\n                nodo.addEventListener('click', () => abrirTelescopio(i));\n                return { nombre, rol, foto: nodo.dataset.foto };\n            });\n            actualizarBotonVoz();\n        }\n\n        // Traza las líneas de la constelación la primera vez que la sección entra en pantalla\n        function animarConstelacion() {\n            const constelacion = document.getElementById('constelacion');\n            const sinMovimiento = window.matchMedia('(prefers-reduced-motion: reduce)').matches;\n            if (sinMovimiento || !('IntersectionObserver' in window)) return;\n            constelacion.classList.add('preparada');\n            const observador = new IntersectionObserver((entradas) => {\n                if (entradas[0].isIntersecting) {\n                    constelacion.classList.add('visible');\n                    constelacion.classList.remove('preparada');\n                    observador.disconnect();\n                }\n            }, { threshold: 0.25 });\n            observador.observe(constelacion);\n        }\n\n        /* ===================== TELESCOPIO 3D ===================== */\n        // Partes del refractor: la descripción se muestra al elegir cada una en la lista\n        const PARTES_TELESCOPIO = [\n            { id: 'objetivo', vista: -60, nombre: 'Objetivo', texto: 'Es la lente grande del frente y capta la luz. Su diámetro, llamado apertura, decide cuánta luz reúne: a mayor apertura, vemos objetos más débiles y con más detalle.' },\n            { id: 'parasol', vista: -30, nombre: 'Parasol', texto: 'Extensión del tubo delante de la lente. Bloquea luces laterales y retrasa el rocío sobre el vidrio, algo muy útil en las noches húmedas de Urabá.' },\n            { id: 'tubo', vista: 20, nombre: 'Tubo óptico', texto: 'Mantiene el objetivo y el ocular alineados a la distancia exacta, la distancia focal. Por dentro es negro mate para que no haya reflejos.' },\n            { id: 'buscador', vista: 15, nombre: 'Buscador', texto: 'Pequeño telescopio auxiliar con poco aumento y una cruz de mira. Primero apuntamos con él al objeto y luego lo vemos en el tubo principal.' },\n            { id: 'enfocador', vista: 140, nombre: 'Enfocador', texto: 'Mecanismo con perillas que acerca o aleja el ocular hasta que la imagen se ve nítida.' },\n            { id: 'ocular', vista: 150, nombre: 'Diagonal y ocular', texto: 'La diagonal desvía la luz 90° para mirar cómodos hacia arriba. El ocular es la lente por donde miramos y se puede cambiar. Aumento = distancia focal del telescopio ÷ distancia focal del ocular. Por ejemplo, 700 mm ÷ 10 mm = 70 aumentos.' },\n            { id: 'montura', vista: 30, nombre: 'Montura', texto: 'Sostiene el tubo y lo deja mover arriba-abajo (altura) y a los lados (azimut) para seguir a los astros mientras cruzan el cielo.' },\n            { id: 'tripode', vista: 30, nombre: 'Trípode', texto: 'Tres patas ajustables que dan estabilidad. Con aumento, cualquier vibración se nota mucho, por eso debe quedar firme y nivelado.' }\n        ];\n\n        // Crea un cilindro 3D con caras planas alrededor del eje X; el sombreado simula una luz fija arriba\n        function crearCilindro({ radio, largo, caras = 20, h, s, l, parte, tapaFrente, tapaAtras }) {\n            const pieza = document.createElement('div');\n            if (parte) pieza.dataset.parte = parte;\n            const anchoCara = Math.ceil((2 * Math.PI * radio) / caras) + 1;\n            for (let i = 0; i < caras; i++) {\n                const angulo = (360 / caras) * i;\n                const luz = Math.cos(((angulo - 60) * Math.PI) / 180);\n                const cara = document.createElement('div');\n                cara.className = 'cara';\n                cara.style.width = `${largo}px`;\n                cara.style.height = `${anchoCara}px`;\n                cara.style.left = `${-largo / 2}px`;\n                cara.style.top = `${-anchoCara / 2}px`;\n                cara.style.background = `hsl(${h}, ${s}%, ${Math.max(6, l + luz * 16)}%)`;\n                cara.style.transform = `rotateX(${angulo}deg) translateZ(${radio}px)`;\n                pieza.appendChild(cara);\n            }\n            // Tapas de los extremos (+X frente, -X atrás)\n            [[1, tapaFrente], [-1, tapaAtras]].forEach(([lado, fondo]) => {\n                const tapa = document.createElement('div');\n                tapa.className = 'tapa';\n                tapa.style.width = tapa.style.height = `${radio * 2}px`;\n                tapa.style.left = tapa.style.top = `${-radio}px`;\n                tapa.style.background = fondo || `hsl(${h}, ${s}%, ${Math.max(6, l - 8)}%)`;\n                tapa.style.transform = `rotateY(${lado * 90}deg) translateZ(${largo / 2}px)`;\n                pieza.appendChild(tapa);\n            });\n            return pieza;\n        }\n\n        // Crea una caja 3D (montura, patas del trípode, soportes)\n        function crearCaja({ ancho, alto, fondo, h, s, l, parte }) {\n            const pieza = document.createElement('div');\n            if (parte) pieza.dataset.parte = parte;\n            const caras = [\n                { w: ancho, hgt: alto, t: `translateZ(${fondo / 2}px)`, luz: 4 },\n                { w: ancho, hgt: alto, t: `rotateY(180deg) translateZ(${fondo / 2}px)`, luz: -10 },\n                { w: fondo, hgt: alto, t: `rotateY(90deg) translateZ(${ancho / 2}px)`, luz: -4 },\n                { w: fondo, hgt: alto, t: `rotateY(-90deg) translateZ(${ancho / 2}px)`, luz: 0 },\n                { w: ancho, hgt: fondo, t: `rotateX(90deg) translateZ(${alto / 2}px)`, luz: 12 },\n                { w: ancho, hgt: fondo, t: `rotateX(-90deg) translateZ(${alto / 2}px)`, luz: -14 }\n            ];\n            caras.forEach(c => {\n                const cara = document.createElement('div');\n                cara.className = 'cara';\n                cara.style.width = `${c.w}px`;\n                cara.style.height = `${c.hgt}px`;\n                cara.style.left = `${-c.w / 2}px`;\n                cara.style.top = `${-c.hgt / 2}px`;\n                cara.style.background = `hsl(${h}, ${s}%, ${Math.max(5, l + c.luz)}%)`;\n                cara.style.transform = c.t;\n                pieza.appendChild(cara);\n            });\n            return pieza;\n        }\n\n        // Posiciona una pieza dentro de su grupo\n        function ubicar(pieza, transformacion) {\n            pieza.style.transform = transformacion;\n            return pieza;\n        }\n\n        function construirTelescopio() {\n            const modelo = document.getElementById('modelo3d');\n            const lente = 'radial-gradient(circle at 38% 35%, rgba(190, 240, 255, 0.95) 0%, rgba(60, 140, 200, 0.9) 35%, rgba(10, 30, 70, 0.95) 75%, #0a0f1f 100%)';\n\n            // Tubo óptico inclinado hacia el cielo, apoyado sobre la montura\n            const tubo = document.createElement('div');\n            tubo.style.transform = 'translateY(-52px) rotateZ(-28deg)';\n            tubo.appendChild(crearCilindro({ radio: 32, largo: 300, caras: 24, h: 222, s: 45, l: 30, parte: 'tubo' }));\n            tubo.appendChild(ubicar(crearCilindro({ radio: 35, largo: 10, caras: 24, h: 42, s: 75, l: 50, parte: 'tubo' }), 'translateX(150px)'));\n            tubo.appendChild(ubicar(crearCilindro({ radio: 35, largo: 10, caras: 24, h: 42, s: 75, l: 50, parte: 'tubo' }), 'translateX(-40px)'));\n            tubo.appendChild(ubicar(crearCilindro({ radio: 39, largo: 80, caras: 24, h: 222, s: 30, l: 16, parte: 'parasol', tapaFrente: 'transparent' }), 'translateX(195px)'));\n            // Lente del objetivo, al fondo del parasol\n            const objetivo = document.createElement('div');\n            objetivo.dataset.parte = 'objetivo';\n            const vidrio = document.createElement('div');\n            vidrio.className = 'tapa';\n            vidrio.style.width = vidrio.style.height = '66px';\n            vidrio.style.left = vidrio.style.top = '-33px';\n            vidrio.style.background = lente;\n            vidrio.style.transform = 'rotateY(90deg)';\n            objetivo.appendChild(vidrio);\n            tubo.appendChild(ubicar(objetivo, 'translateX(157px)'));\n            // Enfocador, diagonal y ocular en la parte trasera\n            tubo.appendChild(ubicar(crearCilindro({ radio: 17, largo: 60, caras: 16, h: 220, s: 8, l: 62, parte: 'enfocador' }), 'translateX(-180px)'));\n            tubo.appendChild(ubicar(crearCaja({ ancho: 14, alto: 16, fondo: 16, h: 42, s: 70, l: 48, parte: 'enfocador' }), 'translateX(-175px) translateY(24px)'));\n            tubo.appendChild(ubicar(crearCilindro({ radio: 13, largo: 34, caras: 12, h: 0, s: 0, l: 20, parte: 'ocular' }), 'translateX(-225px)'));\n            tubo.appendChild(ubicar(crearCilindro({ radio: 10, largo: 46, caras: 12, h: 0, s: 0, l: 14, parte: 'ocular', tapaAtras: lente, tapaFrente: lente }), 'translateX(-238px) translateY(-30px) rotateZ(90deg)'));\n            // Buscador sobre el tubo con sus dos soportes\n            tubo.appendChild(ubicar(crearCilindro({ radio: 9, largo: 110, caras: 12, h: 220, s: 10, l: 70, parte: 'buscador', tapaFrente: lente }), 'translateX(30px) translateY(-56px)'));\n            tubo.appendChild(ubicar(crearCaja({ ancho: 8, alto: 22, fondo: 8, h: 0, s: 0, l: 18, parte: 'buscador' }), 'translateX(0px) translateY(-40px)'));\n            tubo.appendChild(ubicar(crearCaja({ ancho: 8, alto: 22, fondo: 8, h: 0, s: 0, l: 18, parte: 'buscador' }), 'translateX(60px) translateY(-40px)'));\n            modelo.appendChild(tubo);\n\n            // Montura altazimutal: horquilla y eje\n            modelo.appendChild(ubicar(crearCaja({ ancho: 40, alto: 64, fondo: 44, h: 222, s: 20, l: 24, parte: 'montura' }), 'translateY(0px)'));\n            modelo.appendChild(ubicar(crearCilindro({ radio: 9, largo: 70, caras: 12, h: 42, s: 70, l: 45, parte: 'montura' }), 'translateY(-30px) rotateY(90deg)'));\n            modelo.appendChild(ubicar(crearCaja({ ancho: 70, alto: 10, fondo: 70, h: 222, s: 20, l: 20, parte: 'montura' }), 'translateY(36px)'));\n\n            // Trípode: tres patas separadas 120° y abiertas hacia afuera\n            [0, 120, 240].forEach(angulo => {\n                const soporte = document.createElement('div');\n                soporte.style.transform = `translateY(40px) rotateY(${angulo}deg) rotateZ(-20deg)`;\n                soporte.appendChild(ubicar(crearCaja({ ancho: 10, alto: 230, fondo: 12, h: 30, s: 25, l: 32, parte: 'tripode' }), 'translateY(115px)'));\n                soporte.appendChild(ubicar(crearCaja({ ancho: 14, alto: 16, fondo: 16, h: 0, s: 0, l: 12, parte: 'tripode' }), 'translateY(232px)'));\n                modelo.appendChild(soporte);\n            });\n            // Bandeja de accesorios que une las patas\n            modelo.appendChild(ubicar(crearCaja({ ancho: 90, alto: 4, fondo: 90, h: 222, s: 15, l: 22, parte: 'tripode' }), 'translateY(150px) rotateY(45deg)'));\n        }\n\n        function seleccionarParte(id) {\n            const parte = PARTES_TELESCOPIO.find(p => p.id === id);\n            document.getElementById('detalle-titulo').textContent = parte.nombre;\n            document.getElementById('detalle-texto').textContent = parte.texto;\n            document.querySelectorAll('#lista-partes button').forEach(b => b.setAttribute('aria-pressed', String(b.dataset.parte === id)));\n            document.querySelectorAll('#modelo3d [data-parte]').forEach(p => p.classList.toggle('resaltado', p.dataset.parte === id));\n            // Gira el modelo por el camino más corto para que la pieza elegida quede a la vista\n            const actual = ((giroTelescopio % 360) + 360) % 360;\n            let diferencia = parte.vista - actual;\n            diferencia = ((diferencia + 540) % 360) - 180;\n            giroDestino = giroTelescopio + diferencia;\n            if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) { giroTelescopio = giroDestino; giroDestino = null; aplicarGiro(); }\n        }\n\n        function prepararListaPartes() {\n            const lista = document.getElementById('lista-partes');\n            PARTES_TELESCOPIO.forEach(parte => {\n                const item = document.createElement('li');\n                const boton = document.createElement('button');\n                boton.type = 'button';\n                boton.textContent = parte.nombre;\n                boton.dataset.parte = parte.id;\n                boton.addEventListener('click', () => seleccionarParte(parte.id));\n                item.appendChild(boton);\n                lista.appendChild(item);\n            });\n            seleccionarParte('objetivo');\n        }\n\n        // Giro del modelo: automático y lento; se puede arrastrar con mouse/dedo o usar flechas\n        let giroTelescopio = 30;\n        let giroDestino = null;\n        let aplicarGiro = () => {};\n\n        function activarGiroTelescopio() {\n            const escenario = document.getElementById('escenario3d');\n            const modelo = document.getElementById('modelo3d');\n            const sinMovimiento = window.matchMedia('(prefers-reduced-motion: reduce)').matches;\n            let arrastrando = false;\n            let ultimoX = 0;\n            let pausaHasta = 0;\n            const aplicar = () => modelo.style.setProperty('--giro', `${giroTelescopio}deg`);\n            aplicarGiro = aplicar;\n\n            escenario.addEventListener('pointerdown', (e) => {\n                arrastrando = true;\n                giroDestino = null;\n                ultimoX = e.clientX;\n                escenario.setPointerCapture(e.pointerId);\n            });\n            escenario.addEventListener('pointermove', (e) => {\n                if (!arrastrando) return;\n                giroTelescopio += (e.clientX - ultimoX) * 0.6;\n                ultimoX = e.clientX;\n                aplicar();\n            });\n            const soltar = () => { arrastrando = false; pausaHasta = performance.now() + 3000; };\n            escenario.addEventListener('pointerup', soltar);\n            escenario.addEventListener('pointercancel', soltar);\n            escenario.addEventListener('keydown', (e) => {\n                if (e.key === 'ArrowLeft' || e.key === 'ArrowRight') {\n                    e.preventDefault();\n                    giroDestino = null;\n                    giroTelescopio += e.key === 'ArrowLeft' ? -15 : 15;\n                    pausaHasta = performance.now() + 3000;\n                    aplicar();\n                }\n            });\n\n            function girar(ahora) {\n                if (giroDestino !== null) {\n                    // Acercamiento suave hacia la vista de la pieza elegida; luego se queda quieto unos segundos\n                    giroTelescopio += (giroDestino - giroTelescopio) * 0.08;\n                    if (Math.abs(giroDestino - giroTelescopio) < 0.3) { giroTelescopio = giroDestino; giroDestino = null; pausaHasta = ahora + 5000; }\n                    aplicar();\n                } else if (!arrastrando && ahora > pausaHasta) { giroTelescopio += 0.15; aplicar(); }\n                requestAnimationFrame(girar);\n            }\n            aplicar();\n            if (!sinMovimiento) requestAnimationFrame(girar);\n        }\n\n        /* ===================== CIELO PROFUNDO ===================== */\n        // Cada objeto define los tres colores de la nebulosa y datos reales para observarlo desde Turbo (8° N)\n        const TEMAS_CIELO = [\n            { id: 'orion', boton: 'Orión', nombre: 'Nebulosa de Orión (M42)', c1: '#ff4fa3', c2: '#7b3ff2', c3: '#2bb6ff',\n              foto: 'img-cielo/orion-m42.jpg', credito: 'NASA, ESA y M. Robberto (Hubble). Dominio público.', fuente: 'https://commons.wikimedia.org/wiki/File:Orion_Nebula_-_Hubble_2006_mosaic_18000.jpg',\n              texto: 'Una guardería de estrellas a unos 1.344 años luz. Se ve a simple vista como una mancha difusa debajo del cinturón de Orión.',\n              cuando: 'de diciembre a marzo, en las primeras horas de la noche.' },\n            { id: 'vialactea', boton: 'Vía Láctea', nombre: 'Vía Láctea', c1: '#f2c46d', c2: '#3b5bdb', c3: '#c9d6ff',\n              foto: 'img-cielo/via-lactea.jpg', credito: 'ESO/S. Brunier. Licencia CC BY 4.0.', fuente: 'https://commons.wikimedia.org/wiki/File:ESO_-_Milky_Way.jpg',\n              texto: 'Nuestra galaxia: un disco de más de 100.000 años luz con cientos de miles de millones de estrellas. Su centro queda en dirección a Sagitario.',\n              cuando: 'de junio a agosto, lejos de las luces del pueblo.' },\n            { id: 'carina', boton: 'Carina', nombre: 'Nebulosa de Carina (NGC 3372)', c1: '#ff8a3d', c2: '#1fb5a8', c3: '#b05ce0',\n              foto: 'img-cielo/carina.jpg', credito: 'ESO. Licencia CC BY 4.0.', fuente: 'https://commons.wikimedia.org/wiki/File:Carina_Nebula_by_ESO.jpg',\n              texto: 'Una de las nebulosas más grandes del cielo, a unos 7.500 años luz. En su interior está Eta Carinae, una estrella gigante e inestable.',\n              cuando: 'de febrero a mayo, baja sobre el horizonte sur. Por estar cerca del ecuador, desde Turbo sí se alcanza a ver.' },\n            { id: 'pleyades', boton: 'Pléyades', nombre: 'Las Pléyades (M45)', c1: '#7fb8ff', c2: '#2d4fd6', c3: '#d9ecff',\n              foto: 'img-cielo/pleyades.jpg', credito: 'NASA, ESA, AURA/Caltech y Observatorio Palomar. Dominio público.', fuente: 'https://commons.wikimedia.org/wiki/File:Pleiades_large.jpg',\n              texto: 'Un cúmulo de estrellas jóvenes y azules a unos 444 años luz. A simple vista se cuentan seis o siete; con el telescopio, decenas.',\n              cuando: 'de noviembre a febrero, en la constelación de Tauro.' }\n        ];\n\n        function aplicarTemaCielo(id) {\n            const tema = TEMAS_CIELO.find(t => t.id === id);\n            const seccion = document.getElementById('cielo-profundo');\n            seccion.style.setProperty('--c1', tema.c1);\n            seccion.style.setProperty('--c2', tema.c2);\n            seccion.style.setProperty('--c3', tema.c3);\n            document.getElementById('cielo-nombre').textContent = tema.nombre;\n            document.getElementById('cielo-texto').textContent = tema.texto;\n            document.getElementById('cielo-cuando').textContent = tema.cuando;\n            // Foto real del objeto: se desvanece, cambia y vuelve a aparecer\n            const foto = document.getElementById('cielo-foto');\n            foto.classList.add('cambiando');\n            const nueva = new Image();\n            nueva.onload = nueva.onerror = () => {\n                foto.src = tema.foto;\n                foto.alt = `Foto real: ${tema.nombre}`;\n                foto.classList.remove('cambiando');\n            };\n            nueva.src = tema.foto;\n            const credito = document.getElementById('cielo-credito');\n            credito.textContent = `Foto: ${tema.credito} `;\n            const enlace = document.createElement('a');\n            enlace.href = tema.fuente;\n            enlace.target = '_blank';\n            enlace.rel = 'noopener';\n            enlace.textContent = 'Ver fuente';\n            credito.appendChild(enlace);\n            // Muestra solo la figura ilustrada del objeto elegido\n            document.querySelectorAll('#figura-cielo .figura').forEach(f => f.classList.toggle('activa', f.dataset.figura === id));\n            document.getElementById('figura-cielo').setAttribute('aria-label', `Ilustración: ${tema.nombre}`);\n            document.querySelectorAll('#temas-cielo button').forEach(b => b.setAttribute('aria-pressed', String(b.dataset.tema === id)));\n        }\n\n        function prepararCieloProfundo() {\n            const contenedor = document.getElementById('temas-cielo');\n            TEMAS_CIELO.forEach(tema => {\n                const boton = document.createElement('button');\n                boton.type = 'button';\n                boton.dataset.tema = tema.id;\n                const miniatura = document.createElement('img');\n                miniatura.className = 'miniatura-objeto';\n                miniatura.src = tema.foto;\n                miniatura.alt = '';\n                miniatura.style.setProperty('--anillo', tema.c1);\n                boton.append(miniatura, tema.boton);\n                boton.addEventListener('click', () => aplicarTemaCielo(tema.id));\n                contenedor.appendChild(boton);\n            });\n            aplicarTemaCielo('orion');\n        }\n\n        function abrirTelescopio(indice) {\n            if (!integrantes.length) return;\n            document.getElementById('visor-telescopio').classList.add('abierto');\n            mostrarIntegrante(indice);\n        }\n\n        function cerrarTelescopio() {\n            document.getElementById('visor-telescopio').classList.remove('abierto');\n            clearTimeout(temporizadorEnfoque);\n            if ('speechSynthesis' in window) window.speechSynthesis.cancel();\n        }\n\n        function moverTelescopio(paso) {\n            mostrarIntegrante((indiceActual + paso + integrantes.length) % integrantes.length);\n        }\n\n        function mostrarIntegrante(indice) {\n            indiceActual = indice;\n            const persona = integrantes[indice];\n            const imagen = document.getElementById('ocular-imagen');\n            const estado = document.getElementById('ocular-estado');\n            const nombre = document.getElementById('ocular-nombre');\n            const rol = document.getElementById('ocular-rol');\n\n            clearTimeout(temporizadorEnfoque);\n            estado.textContent = 'Enfocando…';\n            nombre.textContent = '';\n            rol.textContent = '';\n\n            // Reinicia la animación de enfoque en cada integrante\n            imagen.classList.remove('enfocando');\n            void imagen.offsetWidth;\n            imagen.src = persona.foto;\n            imagen.alt = `${persona.nombre}, ${persona.rol}`;\n            imagen.classList.add('enfocando');\n\n            // Al terminar de enfocar se revela y se menciona al integrante\n            temporizadorEnfoque = setTimeout(() => {\n                estado.textContent = `Objetivo ${indice + 1} de ${integrantes.length} · En foco`;\n                nombre.textContent = persona.nombre;\n                rol.textContent = persona.rol;\n                anunciar(`Observando a ${persona.nombre}. ${persona.rol}.`);\n            }, 900);\n        }\n\n        // Menciona en voz alta al integrante usando la voz en español del navegador\n        function anunciar(texto) {\n            if (!vozActiva || !('speechSynthesis' in window)) return;\n            window.speechSynthesis.cancel();\n            const mensaje = new SpeechSynthesisUtterance(texto);\n            mensaje.lang = 'es-ES';\n            const vozEspanol = window.speechSynthesis.getVoices().find(v => v.lang && v.lang.toLowerCase().startsWith('es'));\n            if (vozEspanol) mensaje.voice = vozEspanol;\n            mensaje.rate = 1;\n            window.speechSynthesis.speak(mensaje);\n        }\n\n        function alternarVoz() {\n            vozActiva = !vozActiva;\n            try { localStorage.setItem('observatorioVoz', vozActiva ? 'on' : 'off'); } catch (e) { /* sin almacenamiento: solo aplica en esta visita */ }\n            if (!vozActiva && 'speechSynthesis' in window) window.speechSynthesis.cancel();\n            actualizarBotonVoz();\n        }\n\n        function actualizarBotonVoz() {\n            const boton = document.getElementById('btn-voz');\n            if (!('speechSynthesis' in window)) { boton.style.display = 'none'; return; }\n            boton.textContent = vozActiva ? '🔊 Voz activada' : '🔇 Voz desactivada';\n            boton.setAttribute('aria-pressed', String(vozActiva));\n        }\n\n        // Teclado: Esc cierra visores, flechas recorren a los integrantes\n        document.addEventListener('keydown', (e) => {\n            const telescopioAbierto = document.getElementById('visor-telescopio').classList.contains('abierto');\n            if (e.key === 'Escape') { cerrarTelescopio(); cerrarLogo(); }\n            if (telescopioAbierto && e.key === 'ArrowRight') moverTelescopio(1);\n            if (telescopioAbierto && e.key === 'ArrowLeft') moverTelescopio(-1);\n        });\n\n        /* ===================== CIELO ESTRELLADO ===================== */\n        function iniciarCielo() {\n            const canvas = document.getElementById('cielo-estrellado');\n            const ctx = canvas.getContext('2d');\n            const sinMovimiento = window.matchMedia('(prefers-reduced-motion: reduce)').matches;\n            let estrellas = [];\n            let fugaz = null;\n            let ancho = 0, alto = 0;\n\n            function crearEstrellas() {\n                const escala = window.devicePixelRatio || 1;\n                ancho = window.innerWidth;\n                alto = window.innerHeight;\n                canvas.width = ancho * escala;\n                canvas.height = alto * escala;\n                ctx.setTransform(escala, 0, 0, escala, 0, 0);\n                // Densidad proporcional al tamaño de la pantalla\n                const cantidad = Math.floor((ancho * alto) / 3500);\n                const colores = ['255,255,255', '200,230,255', '255,240,200', '102,252,241'];\n                estrellas = Array.from({ length: cantidad }, () => ({\n                    x: Math.random() * ancho,\n                    y: Math.random() * alto,\n                    radio: Math.random() * 1.4 + 0.2,\n                    fase: Math.random() * Math.PI * 2,\n                    velocidad: Math.random() * 0.02 + 0.005,\n                    deriva: Math.random() * 0.05 + 0.01,\n                    color: colores[Math.random() < 0.85 ? 0 : Math.floor(Math.random() * colores.length)]\n                }));\n            }\n\n            function dibujar() {\n                ctx.clearRect(0, 0, ancho, alto);\n                for (const s of estrellas) {\n                    if (!sinMovimiento) {\n                        s.fase += s.velocidad;\n                        s.x -= s.deriva;\n                        if (s.x < 0) s.x = ancho;\n                    }\n                    const brillo = 0.45 + Math.sin(s.fase) * 0.4;\n                    ctx.beginPath();\n                    ctx.arc(s.x, s.y, s.radio, 0, Math.PI * 2);\n                    ctx.fillStyle = `rgba(${s.color},${brillo})`;\n                    ctx.fill();\n                }\n                // Estrella fugaz ocasional\n                if (!sinMovimiento) {\n                    if (!fugaz && Math.random() < 0.004) {\n                        fugaz = { x: Math.random() * ancho * 0.8 + ancho * 0.2, y: Math.random() * alto * 0.4, vida: 1 };\n                    }\n                    if (fugaz) {\n                        const cola = ctx.createLinearGradient(fugaz.x, fugaz.y, fugaz.x + 90, fugaz.y - 45);\n                        cola.addColorStop(0, `rgba(255,255,255,${fugaz.vida})`);\n                        cola.addColorStop(1, 'rgba(255,255,255,0)');\n                        ctx.strokeStyle = cola;\n                        ctx.lineWidth = 2;\n                        ctx.beginPath();\n                        ctx.moveTo(fugaz.x, fugaz.y);\n                        ctx.lineTo(fugaz.x + 90, fugaz.y - 45);\n                        ctx.stroke();\n                        fugaz.x -= 9;\n                        fugaz.y += 4.5;\n                        fugaz.vida -= 0.02;\n                        if (fugaz.vida <= 0) fugaz = null;\n                    }\n                    requestAnimationFrame(dibujar);\n                }\n            }\n\n            crearEstrellas();\n            dibujar();\n            window.addEventListener('resize', () => { crearEstrellas(); if (sinMovimiento) dibujar(); });\n        }\n\n        /* ===================== GUÍA DE ARMADO ===================== */\n        // Pasos para armar distintos telescopios. En el refractor, cada paso resalta su pieza en el modelo 3D.\n        const GUIAS_ARMADO = [\n            {\n                id: 'refractor', nombre: 'Refractor (montura altazimutal)',\n                pasos: [\n                    { titulo: 'Abre y ajusta el trípode', parte: 'tripode',\n                      texto: 'Abre las tres patas del trípode sobre un suelo firme y plano. Ajusta la altura para que el ocular quede cómodo a la altura de tus ojos y aprieta las perillas de cada pata.',\n                      consejo: 'Evita la arena suelta o el pasto blando: cualquier vibración se nota mucho con aumento.' },\n                    { titulo: 'Coloca la bandeja de accesorios', parte: 'tripode',\n                      texto: 'Fija la bandeja entre las patas. Además de guardar los oculares, tensa las patas y le da rigidez al trípode.' },\n                    { titulo: 'Instala la montura', parte: 'montura',\n                      texto: 'Coloca la montura altazimutal sobre la cabeza del trípode y aprieta su tornillo. Comprueba que se mueve suave arriba-abajo (altura) y a los lados (azimut).' },\n                    { titulo: 'Monta el tubo óptico', parte: 'tubo',\n                      texto: 'Apoya el tubo en la montura con el objetivo (la lente grande) hacia adelante y aprieta los tornillos o la abrazadera.',\n                      consejo: 'Sostén el tubo con una mano hasta que quede bien sujeto; si se cae, la lente se puede desalinear o romper.' },\n                    { titulo: 'Coloca el buscador', parte: 'buscador',\n                      texto: 'Desliza el buscador en su soporte sobre el tubo, con su lente mirando hacia el mismo lado que el objetivo, y aprieta el tornillo.' },\n                    { titulo: 'Inserta la diagonal y el ocular', parte: 'ocular',\n                      texto: 'Mete la diagonal en el enfocador y luego el ocular de mayor distancia focal (por ejemplo 25 mm), que da menos aumento y un campo más amplio para empezar. Aprieta los tornillos sin forzar.' },\n                    { titulo: 'Alinea el buscador de día', parte: 'buscador',\n                      texto: 'Apunta a un objeto lejano y fijo, como una antena o un árbol a más de 500 metros. Céntralo en el ocular y luego mueve los tornillos del buscador hasta que su cruz quede sobre el mismo objeto.',\n                      consejo: 'Hazlo de día: de noche es mucho más difícil encontrar un objeto con el buscador desalineado. Nunca uses el Sol como objetivo.' },\n                    { titulo: 'Enfoca y observa', parte: 'enfocador',\n                      texto: 'Quita la tapa del objetivo, apunta con el buscador y gira despacio las perillas del enfocador hasta ver la imagen nítida. La Luna es el mejor primer objetivo.',\n                      consejo: 'Para más aumento, cambia a un ocular de menor distancia focal (10 mm) cuando ya tengas el objeto centrado.' }\n                ]\n            },\n            {\n                id: 'dobson', nombre: 'Reflector newtoniano (Dobson)',\n                pasos: [\n                    { titulo: 'Arma la base Dobson',\n                      texto: 'Une los paneles laterales a la base con los tornillos del kit, siguiendo el manual. Queda una caja en forma de U que gira sobre el suelo.',\n                      consejo: 'Aprieta los tornillos en cruz y de forma pareja para que la base no quede torcida.' },\n                    { titulo: 'Coloca el tubo en la base',\n                      texto: 'Apoya los ejes laterales del tubo (muñones) en las ranuras de la base. El espejo principal queda abajo y la boca del tubo arriba.',\n                      consejo: 'El tubo es pesado y el espejo es delicado: levántalo entre dos personas.' },\n                    { titulo: 'Instala el buscador',\n                      texto: 'Coloca el buscador o el buscador de punto rojo en su soporte, cerca de la boca del tubo.' },\n                    { titulo: 'Pon el ocular',\n                      texto: 'En este telescopio el enfocador está al lado del tubo, cerca de la boca. Inserta ahí el ocular de menor aumento (25 mm) y aprieta el tornillo.' },\n                    { titulo: 'Revisa la colimación',\n                      texto: 'Mira por el enfocador sin ocular (o con un tapón de colimación): los espejos deben verse centrados unos dentro de otros. Si no, gira poco a poco los tornillos del espejo principal, en la parte trasera del tubo.',\n                      consejo: 'Haz ajustes pequeños de un tornillo a la vez y vuelve a mirar después de cada cambio.' },\n                    { titulo: 'Deja que se aclimate',\n                      texto: 'Saca el telescopio al aire libre de 30 a 45 minutos antes de observar. Así el espejo toma la temperatura del aire y la imagen deja de temblar.' },\n                    { titulo: 'Alinea el buscador y observa',\n                      texto: 'Alinea el buscador de día con un objeto lejano, igual que en el refractor. De noche, empuja el tubo con suavidad para seguir a los astros mientras cruzan el cielo.' }\n                ]\n            },\n            {\n                id: 'ecuatorial', nombre: 'Montura ecuatorial',\n                pasos: [\n                    { titulo: 'Arma y nivela el trípode',\n                      texto: 'Abre el trípode, ajusta la altura y usa la burbuja de nivel (si la tiene) para dejar la cabeza horizontal.' },\n                    { titulo: 'Orienta la montura al norte',\n                      texto: 'Coloca la cabeza ecuatorial y gira el trípode para que la pata o la marca \"N\" apunte hacia el norte geográfico. Puedes usar la brújula del celular.' },\n                    { titulo: 'Ajusta la latitud de Turbo',\n                      texto: 'Turbo está a unos 8° de latitud norte. Mueve el tornillo de latitud hasta que la escala de la montura marque 8°.',\n                      consejo: 'Si viajas a otra ciudad, cambia este valor por la latitud de ese lugar.' },\n                    { titulo: 'Instala los contrapesos',\n                      texto: 'Enrosca la barra de contrapeso, pasa el contrapeso y pon el tornillo de seguridad en la punta de la barra.',\n                      consejo: 'El tornillo de seguridad evita que el contrapeso se deslice y caiga sobre un pie.' },\n                    { titulo: 'Monta el tubo óptico',\n                      texto: 'Fija el tubo en las abrazaderas o en la placa tipo cola de milano y aprieta bien.' },\n                    { titulo: 'Balancea el telescopio',\n                      texto: 'Suelta el freno de ascensión recta y mueve el contrapeso hasta que el tubo quede quieto en horizontal. Luego suelta el freno de declinación y desliza el tubo en las abrazaderas hasta que tampoco se incline solo.',\n                      consejo: 'Un telescopio balanceado se mueve suave y los motores o perillas no se fuerzan.' },\n                    { titulo: 'Coloca buscador y ocular',\n                      texto: 'Pon el buscador y un ocular de bajo aumento. Alinea el buscador de día con un objeto lejano.' },\n                    { titulo: 'Haz la alineación polar',\n                      texto: 'De noche, apunta el eje polar de la montura hacia la estrella Polar. Desde Turbo se ve muy baja, a unos 8° sobre el horizonte norte. Así el telescopio sigue a las estrellas moviendo un solo eje.',\n                      consejo: 'Si árboles o edificios tapan el horizonte norte, basta con apuntar el eje polar al norte con la brújula para observaciones sencillas.' }\n                ]\n            }\n        ];\n        let guiaActual = GUIAS_ARMADO[0];\n        let pasoActual = 0;\n        let avanceGuias = {};\n        try { avanceGuias = JSON.parse(localStorage.getItem('guiasObservatorio')) || {}; } catch (e) { avanceGuias = {}; }\n\n        function guardarAvance() {\n            try { localStorage.setItem('guiasObservatorio', JSON.stringify(avanceGuias)); } catch (e) { /* sin almacenamiento: el avance dura solo esta visita */ }\n        }\n\n        function prepararGuias() {\n            const pestanas = document.getElementById('pestanas-guia');\n            GUIAS_ARMADO.forEach(guia => {\n                const boton = document.createElement('button');\n                boton.type = 'button';\n                boton.setAttribute('role', 'tab');\n                boton.dataset.guia = guia.id;\n                boton.textContent = guia.nombre;\n                boton.addEventListener('click', () => seleccionarGuia(guia.id, true));\n                pestanas.appendChild(boton);\n            });\n            seleccionarGuia(GUIAS_ARMADO[0].id, false);\n        }\n\n        function seleccionarGuia(id, porUsuario) {\n            guiaActual = GUIAS_ARMADO.find(g => g.id === id);\n            pasoActual = 0;\n            document.querySelectorAll('#pestanas-guia button').forEach(b => b.setAttribute('aria-selected', String(b.dataset.guia === id)));\n            const indice = document.getElementById('indice-pasos');\n            indice.innerHTML = '';\n            guiaActual.pasos.forEach((paso, i) => {\n                const item = document.createElement('li');\n                const boton = document.createElement('button');\n                boton.type = 'button';\n                const numero = document.createElement('span');\n                numero.className = 'numero-paso';\n                numero.textContent = String(i + 1);\n                boton.append(numero, paso.titulo);\n                boton.addEventListener('click', () => irAPaso(i, true));\n                item.appendChild(boton);\n                indice.appendChild(item);\n            });\n            irAPaso(0, porUsuario);\n        }\n\n        function irAPaso(indice, porUsuario) {\n            pasoActual = indice;\n            const paso = guiaActual.pasos[indice];\n            const hechos = avanceGuias[guiaActual.id] || [];\n            document.getElementById('contador-paso').textContent = `Paso ${indice + 1} de ${guiaActual.pasos.length}`;\n            document.getElementById('titulo-paso').textContent = paso.titulo;\n            document.getElementById('texto-paso').textContent = paso.texto;\n            const consejo = document.getElementById('consejo-paso');\n            consejo.hidden = !paso.consejo;\n            consejo.textContent = paso.consejo ? `💡 ${paso.consejo}` : '';\n            document.getElementById('check-paso').checked = hechos.includes(indice);\n            document.getElementById('btn-paso-anterior').disabled = indice === 0;\n            document.getElementById('btn-paso-siguiente').disabled = indice === guiaActual.pasos.length - 1;\n            document.querySelectorAll('#indice-pasos li').forEach((li, i) => {\n                const boton = li.querySelector('button');\n                boton.classList.toggle('hecho', hechos.includes(i));\n                if (i === indice) boton.setAttribute('aria-current', 'step'); else boton.removeAttribute('aria-current');\n            });\n            document.getElementById('barra-avance-guia').style.width = `${Math.round((hechos.length / guiaActual.pasos.length) * 100)}%`;\n            // En el refractor, el modelo 3D gira y resalta la pieza de este paso\n            if (porUsuario && paso.parte) seleccionarParte(paso.parte);\n        }\n\n        function moverPaso(direccion) {\n            const destino = pasoActual + direccion;\n            if (destino >= 0 && destino < guiaActual.pasos.length) irAPaso(destino, true);\n        }\n\n        function marcarPaso(hecho) {\n            const hechos = new Set(avanceGuias[guiaActual.id] || []);\n            if (hecho) hechos.add(pasoActual); else hechos.delete(pasoActual);\n            avanceGuias[guiaActual.id] = Array.from(hechos);\n            guardarAvance();\n            irAPaso(pasoActual, false);\n        }\n\n        /* ===================== CÓDIGO QR DE LA HISTORIA ===================== */\n        // El QR apunta a la dirección real donde está publicada la página (tu dominio de Hostinger)\n        function generarQR() {\n            const lienzo = document.getElementById('lienzo-qr');\n            const aviso = document.getElementById('qr-no-disponible');\n            const destino = new URL('historia-telescopio.html', location.href).href;\n            const noDisponible = (mensaje) => {\n                lienzo.hidden = true;\n                aviso.hidden = false;\n                if (mensaje) aviso.textContent = mensaje;\n                document.getElementById('btn-descargar-qr').disabled = true;\n            };\n            if (location.protocol === 'file:') { noDisponible(); return; }\n            if (typeof qrcode !== 'function') { noDisponible('No se pudo cargar el generador del código QR. Revisa que la carpeta js/ esté subida al servidor.'); return; }\n            const codigo = qrcode(0, 'M');\n            codigo.addData(destino);\n            codigo.make();\n            // Margen de 4 módulos alrededor, como pide el estándar para que el celular lo lea bien\n            const modulos = codigo.getModuleCount();\n            const margen = 4;\n            const celda = Math.floor(1000 / (modulos + margen * 2));\n            const tamano = celda * (modulos + margen * 2);\n            lienzo.width = tamano;\n            lienzo.height = tamano;\n            const ctx = lienzo.getContext('2d');\n            ctx.fillStyle = '#ffffff';\n            ctx.fillRect(0, 0, tamano, tamano);\n            ctx.fillStyle = '#0b0c10';\n            for (let fila = 0; fila < modulos; fila++) {\n                for (let col = 0; col < modulos; col++) {\n                    if (codigo.isDark(fila, col)) ctx.fillRect((col + margen) * celda, (fila + margen) * celda, celda, celda);\n                }\n            }\n            document.getElementById('url-qr').textContent = destino;\n        }\n\n        function descargarQR() {\n            const lienzo = document.getElementById('lienzo-qr');\n            lienzo.toBlob(archivo => {\n                const enlace = document.createElement('a');\n                enlace.href = URL.createObjectURL(archivo);\n                enlace.download = 'qr-historia-telescopio.png';\n                document.body.appendChild(enlace);\n                enlace.click();\n                enlace.remove();\n                setTimeout(() => URL.revokeObjectURL(enlace.href), 1000);\n            }, 'image/png');\n        }\n\n        /* ===================== CUENTAS DE COMPAÑEROS ===================== */\n        const API_CUENTAS = '/api/cuentas.php';\n        let cuentaActual = null;\n\n        function mostrarFormularioCuenta(cual) {\n            document.getElementById('form-ingresar').hidden = cual !== 'ingresar';\n            document.getElementById('form-registrar').hidden = cual !== 'registrar';\n            document.getElementById('pestana-ingresar').setAttribute('aria-selected', String(cual === 'ingresar'));\n            document.getElementById('pestana-registrar').setAttribute('aria-selected', String(cual === 'registrar'));\n        }\n\n        function alternarClave(id, boton) {\n            const campo = document.getElementById(id);\n            const visible = campo.type === 'text';\n            campo.type = visible ? 'password' : 'text';\n            boton.textContent = visible ? 'Mostrar' : 'Ocultar';\n        }\n\n        function estadoCuenta(formulario, texto, clase = '') {\n            const estado = document.getElementById(`estado-${formulario}`);\n            estado.textContent = texto;\n            estado.className = 'estado-cuenta' + (clase ? ' ' + clase : '');\n        }\n\n        // Sin servidor PHP (archivo abierto en el PC o publicación sin PHP) el registro no puede funcionar\n        function cuentasNoDisponibles() {\n            const aviso = document.getElementById('aviso-cuentas');\n            aviso.hidden = false;\n            aviso.textContent = location.protocol === 'file:'\n                ? '💻 Estás viendo la página desde tu PC. El registro de compañeros funciona cuando la página está publicada en Hostinger.'\n                : 'El registro no está disponible en esta versión de la página porque no tiene servidor.';\n            document.querySelectorAll('#tarjeta-cuenta input, #tarjeta-cuenta button').forEach(el => { el.disabled = true; });\n        }\n\n        async function consultarSesion() {\n            if (location.protocol === 'file:') { cuentasNoDisponibles(); return; }\n            try {\n                const respuesta = await fetch(API_CUENTAS, { cache: 'no-store', credentials: 'same-origin' });\n                const datos = await respuesta.json();\n                if (!respuesta.ok || !datos.ok) throw new Error();\n                actualizarVistaCuenta(datos.usuario, datos.miembros || []);\n            } catch (e) {\n                cuentasNoDisponibles();\n            }\n        }\n\n        function actualizarVistaCuenta(usuario, miembros) {\n            cuentaActual = usuario;\n            document.getElementById('bloque-acceso').hidden = !!usuario;\n            document.getElementById('bloque-sesion').hidden = !usuario;\n            document.getElementById('enlace-cuenta').textContent = usuario ? `👤 ${usuario.nombre.split(' ')[0]}` : 'Ingresar';\n            // En la bitácora, quien tiene sesión publica con su nombre verificado\n            document.getElementById('campo-autor').hidden = !!usuario;\n            const publicarComo = document.getElementById('publicar-como');\n            publicarComo.hidden = !usuario;\n            if (!usuario) return;\n            publicarComo.textContent = `Publicarás como ${usuario.nombre} ✔`;\n            document.getElementById('saludo-sesion').textContent = `Hola, ${usuario.nombre}`;\n            document.getElementById('usuario-sesion').textContent = `Usuario: ${usuario.usuario}`;\n            const lista = document.getElementById('lista-miembros');\n            lista.innerHTML = '';\n            miembros.forEach(miembro => {\n                const item = document.createElement('li');\n                const nombre = document.createElement('strong');\n                nombre.textContent = miembro.nombre;\n                const desde = document.createElement('span');\n                desde.textContent = `desde ${new Date(miembro.desde).toLocaleDateString('es-CO', { day: 'numeric', month: 'short', year: 'numeric' })}`;\n                item.append(nombre, desde);\n                lista.appendChild(item);\n            });\n        }\n\n        async function enviarCuenta(event, accion) {\n            event.preventDefault();\n            const cual = accion === 'iniciar' ? 'ingresar' : 'registrar';\n            const formulario = new FormData();\n            formulario.append('accion', accion);\n            if (accion === 'iniciar') {\n                formulario.append('usuario', document.getElementById('ingreso-usuario').value.trim());\n                formulario.append('clave', document.getElementById('ingreso-clave').value);\n            } else {\n                const clave = document.getElementById('registro-clave').value;\n                if (clave !== document.getElementById('registro-clave2').value) {\n                    estadoCuenta(cual, 'Las contraseñas no coinciden. Escríbelas de nuevo.', 'error');\n                    return;\n                }\n                formulario.append('nombre', document.getElementById('registro-nombre').value.trim());\n                formulario.append('usuario', document.getElementById('registro-usuario').value.trim());\n                formulario.append('clave', clave);\n            }\n            const boton = event.target.querySelector('button[type=\"submit\"]');\n            boton.disabled = true;\n            estadoCuenta(cual, accion === 'iniciar' ? 'Verificando…' : 'Creando tu cuenta…');\n            try {\n                const respuesta = await fetch(API_CUENTAS, { method: 'POST', body: formulario, credentials: 'same-origin' });\n                const datos = await respuesta.json().catch(() => ({}));\n                if (!respuesta.ok || !datos.ok) throw new Error(datos.error || `El servidor respondió con error ${respuesta.status}.`);\n                event.target.reset();\n                estadoCuenta(cual, '');\n                await consultarSesion();\n                await cargarMedia();\n            } catch (error) {\n                estadoCuenta(cual, error.message, 'error');\n            } finally {\n                boton.disabled = false;\n            }\n        }\n\n        async function cerrarSesion() {\n            const formulario = new FormData();\n            formulario.append('accion', 'cerrar');\n            try { await fetch(API_CUENTAS, { method: 'POST', body: formulario, credentials: 'same-origin' }); } catch (e) { /* si falla la red, igual se recarga */ }\n            // Con el ingreso obligatorio, al cerrar sesión el servidor muestra la pantalla de ingreso\n            location.replace('./');\n        }\n\n        document.addEventListener('DOMContentLoaded', () => {\n            iniciarCielo();\n            prepararIntegrantes();\n            animarConstelacion();\n            construirTelescopio();\n            prepararListaPartes();\n            activarGiroTelescopio();\n            prepararCieloProfundo();\n            prepararActividades();\n            prepararGuias();\n            generarQR();\n            consultarSesion();\n            // Algunas voces del navegador cargan tarde; se solicitan de antemano\n            if ('speechSynthesis' in window) window.speechSynthesis.getVoices();\n        });\n    </script>\n</body>\n</html>";
